import { describe, expect, it } from "bun:test";
import { readFileSync } from "node:fs";
import { join, resolve } from "node:path";

const REPO_ROOT = resolve(import.meta.dir, "..", "..");
const PROMPT = join(REPO_ROOT, "prompts/review-prompt.md");

const EXPECTED_RULE = `- If test execution is unavailable because of the
  reviewer's environment rather than the diff — for example, the sandbox is
  read-only or a probe dies with \`EPERM\` — that is never a \`blocker\`.
  Record it in \`notes\` with the \`[env]\` prefix, keep
  \`bug_free_confidence\` in the 70–89 band you can actually defend, and
  finish the verdict from static review plus the CI snapshot. The
  deterministic suites are separate required checks and still have to pass
  on their own. Do not retry indefinitely.`;

function normalize(value: string): string {
  return value.replace(/\s+/g, " ").trim();
}

describe("review prompt: environment failures are never blockers", () => {
  const markdown = readFileSync(PROMPT, "utf8");

  it("keeps the causation-based environment rule intact", () => {
    expect(normalize(markdown)).toContain(normalize(EXPECTED_RULE));
  });

  it("does not restore the contradictory instruction", () => {
    expect(normalize(markdown)).not.toContain(
      "If the environment itself is broken (e.g. you cannot run even a narrow test file), record that as a `blocker`"
    );
  });

  it("keeps blockers tied to a failure the diff caused", () => {
    expect(markdown).toMatch(/actually failed and the diff is\s+the cause/);
  });
});

