export default async (ctx, client) => {
  // #2299/#2300: device-pinned connections must be one-per-device.
  // Read the raw rows so we see whatever pin/profile columns exist.
  const rows = await client.query(
    `SELECT * FROM connections WHERE connector_key IN ('apple.computer_use','chrome') ORDER BY id`
  );
  const list = Array.isArray(rows) ? rows : (rows?.rows ?? rows?.data ?? []);
  return {
    columns: list.length ? Object.keys(list[0]) : [],
    rows: list.map((r) => {
      const out = {};
      for (const [k, v] of Object.entries(r)) {
        if (/id$|slug|connector|status|device|pin|profile|owner|visibility/i.test(k)) out[k] = v;
      }
      return out;
    }),
  };
};

export default async (ctx, client) => {
  const all = await client.query(
    `SELECT id, connector_key, slug, status, visibility, device_worker_id, deleted_at
       FROM connections WHERE device_worker_id IS NOT NULL ORDER BY device_worker_id, id`
  );
  const rows = Array.isArray(all) ? all : (all?.rows ?? all?.data ?? []);
  const byDevice = {};
  for (const r of rows) (byDevice[r.device_worker_id] ??= []).push(`${r.id}:${r.slug}:${r.status}${r.deleted_at ? ":DELETED" : ""}`);
  const dupes = Object.entries(byDevice).filter(([, v]) => v.filter((x) => !x.endsWith(":DELETED")).length > 1);

  // Device-pinned connector definitions that have an ACTIVE connection with no pin.
  const unpinned = await client.query(
    `SELECT c.id, c.slug, c.connector_key, c.status, c.visibility
       FROM connections c
      WHERE c.device_worker_id IS NULL AND c.deleted_at IS NULL AND c.status = 'active'
        AND (c.connector_key LIKE 'apple.%' OR c.connector_key LIKE 'chrome%'
             OR c.connector_key LIKE 'local.%' OR c.connector_key LIKE '%.local')
      ORDER BY c.id`
  );
  return {
    total_pinned_connections: rows.length,
    distinct_devices: Object.keys(byDevice).length,
    devices_with_multiple_live_connections: dupes,
    active_device_connectors_missing_a_pin: Array.isArray(unpinned) ? unpinned : (unpinned?.rows ?? unpinned),
  };
};

export default async (ctx, client) => {
  const dupes = await client.query(
    `SELECT device_worker_id, connector_key, COUNT(*) AS n,
            STRING_AGG(id || ':' || slug || ':' || status, ', ' ORDER BY id) AS rows
       FROM connections
      WHERE device_worker_id IS NOT NULL AND deleted_at IS NULL
      GROUP BY device_worker_id, connector_key HAVING COUNT(*) > 1`
  );
  const orphan = await client.query(
    `SELECT id, slug, connector_key, status, visibility, created_at, updated_at, created_by, config
       FROM connections WHERE id = 397`
  );
  const twin = await client.query(
    `SELECT id, slug, status, visibility, device_worker_id, updated_at
       FROM connections WHERE connector_key = 'apple.computer_use' AND deleted_at IS NULL ORDER BY id`
  );
  const g = (x) => (Array.isArray(x) ? x : (x?.rows ?? x?.data ?? []));
  return {
    duplicate_device_connector_pairs: g(dupes),
    computer_use_connections: g(twin),
    orphan_397: g(orphan).map((r) => ({ ...r, config: JSON.stringify(r.config)?.slice(0, 200) })),
  };
};

export default async (ctx, client) => {
  const agents = await client.agents?.list ? await client.agents.list({}) : null;
  const g = (x) => (Array.isArray(x) ? x : (x?.rows ?? x?.data ?? x?.items ?? x));
  return { agents: g(agents) };
};

