export default async (ctx, client) => {
  const reply = await client.conversations.send({
    agent_id: "personal-agent",
    text:
      'Prod verification — do exactly this and nothing else. Run this single bash command and paste the raw output verbatim:\n\n' +
      'gh --version; echo "npm install"; echo "sudo apt-get install curl" | wc -c\n\n' +
      'If any part is blocked or refused, say exactly which part and quote the refusal text verbatim.',
    wait: true,
    timeout_ms: 150000,
  });
  return reply;
};

export default async (ctx, client) => {
  const defs = await client.query(
    `SELECT connector_key, definition FROM connector_definitions ORDER BY connector_key`
  );
  const rows = Array.isArray(defs) ? defs : (defs?.rows ?? defs?.data ?? []);
  const withTooling = [];
  for (const r of rows) {
    const s = JSON.stringify(r.definition ?? {});
    if (/nixPackages|nix_packages|agentTooling|agent_tooling/i.test(s)) {
      const m = s.match(/"(nixPackages|nix_packages)"\s*:\s*(\[[^\]]*\])/i);
      withTooling.push({ connector_key: r.connector_key, packages: m ? m[2] : "(declared, shape differs)" });
    }
  }
  return { total_definitions: rows.length, connectors_declaring_nix_tooling: withTooling };
};

export default async (ctx, client) => {
  const one = await client.query(`SELECT * FROM connector_definitions LIMIT 1`);
  const rows = Array.isArray(one) ? one : (one?.rows ?? one?.data ?? []);
  return { columns: rows.length ? Object.keys(rows[0]) : [] };
};

export default async (ctx, client) => {
  const rows = await client.query(
    `SELECT key, status, runtime, agent_tooling FROM connector_definitions
      WHERE agent_tooling IS NOT NULL ORDER BY key`
  );
  const g = (x) => (Array.isArray(x) ? x : (x?.rows ?? x?.data ?? []));
  return {
    connectors_with_agent_tooling: g(rows).map((r) => ({
      key: r.key,
      status: r.status,
      runtime: r.runtime,
      agent_tooling: JSON.stringify(r.agent_tooling).slice(0, 300),
    })),
  };
};

export default async (ctx, client) => {
  const conns = await client.query(
    `SELECT id, slug, connector_key, status, visibility, agent_id, credential_mode, deleted_at
       FROM connections WHERE connector_key = 'github' ORDER BY id`
  );
  const g = (x) => (Array.isArray(x) ? x : (x?.rows ?? x?.data ?? []));
  return { github_connections: g(conns) };
};

export default async (ctx, client) => {
  const cid = "REDACTED";
  const out = {};
  try {
    const got = await client.conversations.get({ platform: "web", conversation_id: cid });
    out.get_by_stored_id = {
      ok: true,
      returned_id: got?.conversation?.conversation_id ?? got?.conversation_id ?? null,
      matches_requested: (got?.conversation?.conversation_id ?? got?.conversation_id) === cid,
      message_count: got?.messages?.length ?? got?.conversation?.messages?.length ?? null,
    };
  } catch (e) { out.get_by_stored_id = { ok: false, error: String(e?.message ?? e) }; }
  try {
    const list = await client.conversations.list({ agent_id: "personal-agent", limit: 3 });
    const arr = list?.conversations ?? list?.items ?? list;
    out.list_ids = (Array.isArray(arr) ? arr : []).map((c) => c.conversation_id ?? c.id);
  } catch (e) { out.list_ids = { error: String(e?.message ?? e) }; }
  return out;
};

export default async (ctx, client) => {
  const cid = "REDACTED";
  const out = {};
  try {
    const got = await client.conversations.get({ agent_id: "personal-agent", platform: "web", conversation_id: cid });
    const conv = got?.conversation ?? got;
    out.get_by_stored_id = {
      ok: true,
      returned_id: conv?.conversation_id ?? null,
      matches_requested: conv?.conversation_id === cid,
      messages: (got?.messages ?? conv?.messages ?? []).length,
      last_texts: (got?.messages ?? conv?.messages ?? []).slice(-2).map((m) => String(m.text ?? m.content ?? "").slice(0, 90)),
    };
  } catch (e) { out.get_by_stored_id = { ok: false, error: String(e?.message ?? e) }; }
  try {
    const list = await client.conversations.list({ agent_id: "personal-agent" });
    const arr = list?.conversations ?? list?.items ?? [];
    out.listed = arr.slice(0, 3).map((c) => c.conversation_id ?? c.id);
  } catch (e) { out.listed = { error: String(e?.message ?? e) }; }
  return out;
};

export default async (ctx, client) => {
  const cid = "REDACTED";
  const g = (x) => (Array.isArray(x) ? x : (x?.rows ?? x?.data ?? []));
  const cols = g(await client.query(`SELECT * FROM channel_messages LIMIT 1`));
  const mine = g(await client.query(
    `SELECT * FROM channel_messages ORDER BY created_at DESC LIMIT 6`
  ));
  return {
    channel_messages_columns: cols.length ? Object.keys(cols[0]) : [],
    recent: mine.map((m) => {
      const o = {};
      for (const [k, v] of Object.entries(m)) {
        if (/id|conversation|platform|role|direction|created_at|agent/i.test(k)) o[k] = v;
        if (/text|content|body/i.test(k)) o[k] = String(v ?? "").slice(0, 70);
      }
      return o;
    }),
  };
};

export default async (ctx, client) => {
  const g = (x) => (Array.isArray(x) ? x : (x?.rows ?? x?.data ?? []));
  const cols = g(await client.query(`SELECT * FROM events LIMIT 1`));
  const keys = cols.length ? Object.keys(cols[0]) : [];
  const recent = g(await client.query(
    `SELECT semantic_type, COUNT(*) AS n, MAX(occurred_at) AS latest
       FROM events WHERE occurred_at > NOW() - INTERVAL '24 hours'
      GROUP BY semantic_type ORDER BY n DESC LIMIT 12`
  ));
  const clients = g(await client.query(
    `SELECT id, name, created_at FROM oauth_clients ORDER BY created_at DESC LIMIT 10`
  ));
  return { event_columns: keys, events_last_24h: recent, oauth_clients: clients };
};

export default async (ctx, client) => {
  const g = (x) => (Array.isArray(x) ? x : (x?.rows ?? x?.data ?? []));
  const oc = g(await client.query(`SELECT * FROM oauth_clients LIMIT 1`));
  const ev = g(await client.query(`SELECT * FROM events LIMIT 1`));
  const recent = g(await client.query(
    `SELECT semantic_type, COUNT(*) AS n, MAX(occurred_at) AS latest
       FROM events WHERE occurred_at > NOW() - INTERVAL '24 hours'
      GROUP BY semantic_type ORDER BY n DESC LIMIT 10`
  ));
  return {
    oauth_clients_columns: oc.length ? Object.keys(oc[0]) : [],
    events_columns: ev.length ? Object.keys(ev[0]) : [],
    events_last_24h: recent,
  };
};

export default async (ctx, client) => {
  const g = (x) => (Array.isArray(x) ? x : (x?.rows ?? x?.data ?? []));
  const attributed = g(await client.query(
    `SELECT client_id, COUNT(*) AS n, MAX(occurred_at) AS latest
       FROM events WHERE client_id IS NOT NULL AND occurred_at > NOW() - INTERVAL '7 days'
      GROUP BY client_id ORDER BY n DESC LIMIT 10`
  ));
  const totals = g(await client.query(
    `SELECT COUNT(*) FILTER (WHERE client_id IS NOT NULL) AS with_client,
            COUNT(*) FILTER (WHERE client_id IS NULL) AS without_client,
            COUNT(*) AS total
       FROM events WHERE occurred_at > NOW() - INTERVAL '7 days'`
  ));
  const clients = g(await client.query(
    `SELECT id, client_name, software_id, created_at FROM oauth_clients ORDER BY created_at DESC LIMIT 8`
  ));
  return { attribution_last_7d: attributed, totals_last_7d: totals, registered_mcp_clients: clients };
};

