export default async (ctx, client) => {
  const c = client.org("owletto");
  const rows = await c.query(`
    SELECT cache_key, expires_at, created_at, updated_at
    FROM chat_state_cache
    WHERE cache_key LIKE 'dedupe:telegram:6570514069:%'
    ORDER BY (split_part(cache_key, ':', 4))::int
  `);
  return { count: rows.length, rows };
};

export default async (ctx, client) => {
  const orgs = await client.organizations.list();
  return { current: ctx.organization_id, orgs };
};

export default async (ctx, client) => {
  const out = {};
  try {
    out.rows = await client.query(`
      SELECT cache_key, expires_at, created_at
      FROM chat_state_cache
      WHERE cache_key LIKE 'dedupe:telegram:6570514069:%'
      ORDER BY created_at
      LIMIT 100
    `);
  } catch (e) { out.err = String(e.message || e); }
  try {
    out.conn = await client.query(`
      SELECT id, display_name, connector_key, status
      FROM connections WHERE connector_key = 'telegram'
    `);
  } catch (e) { out.connErr = String(e.message || e); }
  return out;
};

export default async (ctx, client) => {
  const rows = await client.query(`
    SELECT id, connection_id, channel_id, external_message_id, direction, created_at,
           left(coalesce(content,''), 60) AS preview
    FROM channel_messages
    WHERE channel_id = '6570514069'
    ORDER BY created_at DESC
    LIMIT 25
  `);
  return rows;
};

export default async (ctx, client) => {
  const one = await client.query(`SELECT * FROM channel_messages ORDER BY created_at DESC LIMIT 1`);
  return { columns: one.length ? Object.keys(one[0]) : [], sample: one[0] };
};

export default async (ctx, client) => {
  const rows = await client.query(`
    SELECT id, platform_message_id, is_bot, occurred_at, left(coalesce(text,''),50) AS preview
    FROM channel_messages
    WHERE channel_id = '6570514069'
    ORDER BY id DESC
    LIMIT 30
  `);
  return rows;
};

