21	  writeFileSync,
22	} from "node:fs";
23	import { tmpdir } from "node:os";
24	import { join } from "node:path";
25	import { createLobuResourceLoader } from "../runtime/pi-resources";
26	import { buildAgentSession } from "../runtime/session-runner";
27	import { createLobuTools } from "../runtime/tools";
28	
29	let workspace: string;
30	
31	beforeEach(() => {
32	  workspace = mkdtempSync(join(tmpdir(), "pi-discovery-"));
33	});
34	afterEach(() => {
35	  rmSync(workspace, { recursive: true, force: true });
36	});
37	
38	function seed(relativePath: string, content: string): void {
39	  const full = join(workspace, relativePath);
40	  mkdirSync(join(full, ".."), { recursive: true });
41	  writeFileSync(full, content, "utf-8");
42	}
43	
44	async function boot() {
45	  const tools = createLobuTools(workspace);
46	  const { session } = await buildAgentSession({
47	    cwd: workspace,
