362	  ): Promise<void> {
363	    const ctx = this.extractResponseContext(payload);
364	    if (!ctx) return;
365	
366	    const { connectionId, strategy, channelId } = ctx;
367	    const key = `${channelId}:${payload.conversationId}`;
368	
369	    const stream = this.streams.get(key);
370	    if (stream) {
371	      // Close the iterator and drain the in-flight post regardless of
372	      // strategy — Slack's iterator is already closed (no-op), default's
373	      // needs explicit close+await before final delivery steps run.
374	      stream.iterator.close();
375	      try {
376	        await stream.streamPromise;
377	      } catch (error) {
378	        logger.debug(
379	          { connectionId, error: String(error) },
380	          "Adapter stream errored during completion"
381	        );
382	      }
383	    }
384	
385	    // Deliver when this replica has a local stream OR when this is a post-once
386	    // strategy (Slack) carrying the worker's full text. Under N>1 replicas the
387	    // delta rows and the terminal row are claimed competitively from the shared
388	    // `thread_response` queue with no per-conversation affinity, so the
389	    // completion can land on a pod that buffered no (or only some) deltas — only
390	    // `payload.finalText` is authoritative there. A live-streaming strategy with
391	    // no local stream already posted its deltas on the claiming replica, so it
392	    // is intentionally skipped (re-posting would duplicate).
393	    const canDeliverFromFinalText =
394	      strategy.deliversAtCompletion && !!payload.finalText?.trim();
395	
