/**
 * Chat identity is a property of being a chat connection, not of being Slack.
 *
 * Telegram (and every other platform that declares no instruction provider)
 * used to receive NO identity instructions at all. The agent then had only its
 * own identity markdown, which describes the principal in the third person, and
 * answered as an observer — "Burak sent a message … how would you like to
 * respond?" — to an operator that does not exist.
 *
 * The cross-tenant guard is inherited from the same code path Slack uses, so it
 * is asserted here for the generic provider too: a shared agent id exists in
 * many orgs, and an unscoped `listConnections` returns another tenant's newest
 * connection.
 */

import { describe, expect, test } from "bun:test";
import type { InstructionContext } from "@lobu/core";
import { orgContext } from "../../../lobu/stores/org-context.js";
import { ChatIdentityInstructionProvider } from "../chat-identity-instruction-provider.js";
import { SlackInstructionProvider } from "../slack-instruction-provider.js";

function ctx(overrides: Partial<InstructionContext>): InstructionContext {
  return {
    userId: "u1",
    agentId: "personal-agent",
    sessionKey: "u1",
    workingDirectory: "/workspace",
    availableProjects: [],
    ...overrides,
  };
}

function managerReturning(
  connections: Array<{ metadata: Record<string, string> }>,
  onList?: (filter: { platform?: string }) => void
) {
  return {
    listConnections: async (filter: { platform?: string }) => {
      onList?.(filter);
      return connections;
    },
  } as never;
}

describe("ChatIdentityInstructionProvider", () => {
  test("telegram gets an identity AND participant framing", async () => {
    const provider = new ChatIdentityInstructionProvider(
      managerReturning([
        {
          metadata: {
            botUsername: "burembalobubot",
            botUserId: "8834276769",
          },
        },
      ]),
      "telegram"
    );

    const result = await provider.getInstructions(
      ctx({ organizationId: "buremba" })
    );

    // Identity: who am I.
    expect(result).toContain("@burembalobubot");
    expect(result).toContain("8834276769");
    expect(result).toContain("Telegram");
    // Participation: the half that stops the observer voice. Without this the
    // agent narrates the conversation instead of taking part in it.
    expect(result).toContain("participant in this conversation");
    expect(result).toContain("addressed to you");
    expect(result.toLowerCase()).toContain("do not describe them in the third");
  });

  test("queries connections for its OWN platform, not slack", async () => {
    const seen: Array<string | undefined> = [];
    const provider = new ChatIdentityInstructionProvider(
      managerReturning(
        [{ metadata: { botUsername: "wa-bot" } }],
        (filter) => seen.push(filter.platform)
      ),
      "whatsapp"
    );

    await provider.getInstructions(ctx({ organizationId: "acme" }));

    expect(seen).toEqual(["whatsapp"]);
  });

  test("orgless context returns '' and never reads connections", async () => {
    let listCalled = false;
    const provider = new ChatIdentityInstructionProvider(
      managerReturning(
        [{ metadata: { botUsername: "foreign-bot", botUserId: "UFOREIGN" } }],
        () => {
          listCalled = true;
        }
      ),
      "telegram"
    );

    const result = await provider.getInstructions(
      ctx({ organizationId: undefined })
    );

    expect(result).toBe("");
    expect(listCalled).toBe(false);
  });

  test("reads connections INSIDE the token org", async () => {
    let seenOrg: string | undefined;
    const provider = new ChatIdentityInstructionProvider(
      managerReturning([{ metadata: { botUsername: "acme-bot" } }], () => {
        seenOrg = orgContext.getStore()?.organizationId;
      }),
      "telegram"
    );

    await provider.getInstructions(ctx({ organizationId: "acme-org" }));

    expect(seenOrg).toBe("acme-org");
  });

  test("a connection with no bot identity yields '' rather than a half-sentence", async () => {
    const provider = new ChatIdentityInstructionProvider(
      managerReturning([{ metadata: {} }]),
      "telegram"
    );

    const result = await provider.getInstructions(
      ctx({ organizationId: "acme" })
    );

    expect(result).toBe("");
  });

  test("PROMPT CACHE: output is connection-scoped only — identical across conversations", async () => {
    // These instructions sit at the front of `gatewayInstructions`, and the
    // openai-completions path caches by longest common prefix with no explicit
    // breakpoints. If anything conversation-scoped (sender, channel, session)
    // reached this string, every new conversation would get a unique prefix and
    // lose the cache. Two different sessions/users on ONE connection must
    // therefore render byte-identical.
    const provider = new ChatIdentityInstructionProvider(
      managerReturning([
        { metadata: { botUsername: "burembalobubot", botUserId: "8834276769" } },
      ]),
      "telegram"
    );

    const first = await provider.getInstructions(
      ctx({ organizationId: "buremba", userId: "user-a", sessionKey: "chat-1" })
    );
    const second = await provider.getInstructions(
      ctx({ organizationId: "buremba", userId: "user-b", sessionKey: "chat-2" })
    );

    expect(first).toBe(second);
    expect(first).not.toContain("user-a");
    expect(first).not.toContain("chat-1");
  });
});

describe("SlackInstructionProvider still adds its own quirks", () => {
  test("keeps mention guidance on top of the shared framing", async () => {
    const provider = new SlackInstructionProvider(
      managerReturning([
        { metadata: { botUsername: "acme-bot", botUserId: "UACME" } },
      ])
    );

    const result = await provider.getInstructions(
      ctx({ organizationId: "acme-org" })
    );

    // Slack-specific delta.
    expect(result).toContain("<@UACME>");
    // Shared framing is inherited, not restated.
    expect(result).toContain("participant in this conversation");
    expect(result).toContain("@acme-bot");
  });
});

