 * An agent reached over a chat connection needs two facts that nothing else in
 * the prompt supplies: WHO it is in that conversation, and that the messages it
 * receives are addressed TO it. Without them the agent has only its
 * identity/soul markdown, which describes the principal in the third person
 * ("you work on the user's data on their behalf") and never says the person
 * currently typing IS that principal. A capable model resolves that gap the
 * wrong way: it treats the inbound message as observed conversation about a
 * third party and narrates it back — "Burak sent a message … how would you like
 * to respond?" — addressing an operator who does not exist.
 *
 * Slack never showed this because `SlackInstructionProvider` happened to state
 * "You are reachable in Slack as `@x`", which is enough to establish
 * participation. Every platform that did not declare an instruction provider
 * (Telegram, WhatsApp, …) got nothing. This provider is the default for all of
 * them, so the framing is a property of being a chat connection rather than
 * something each platform re-derives.
 *
 * PROMPT-CACHE CONTRACT — read before adding a line here.
 * These instructions sit at the FRONT of `gatewayInstructions`
 * (`session-context.ts`), and the Gemini/OpenAI-completions path has no
 * explicit cache breakpoints: reuse is longest-common-prefix only. Everything
 * emitted here must therefore be CONNECTION-scoped (platform, bot handle, bot
 * id) — values that are constant for the life of the connection, so every
 * conversation on it shares one prefix. Never interpolate anything
 * CONVERSATION-scoped (the sender's name, channel/chat id, message text,
 * timestamps): that hands every new conversation a unique prefix and forfeits
 * the cache for all of them.
 */
import { BaseInstructionProvider, type InstructionContext } from "@lobu/core";
import { orgContext } from "../../lobu/stores/org-context.js";
import type { ChatInstanceManager } from "./chat-instance-manager.js";

/** Human-facing platform label; falls back to the raw key. */
const PLATFORM_LABELS: Record<string, string> = {
  slack: "Slack",
  telegram: "Telegram",
  whatsapp: "WhatsApp",
  discord: "Discord",
  teams: "Microsoft Teams",
  gchat: "Google Chat",
};

export function platformLabel(platform: string): string {
  return PLATFORM_LABELS[platform] ?? platform;
}

export interface ChatBotIdentity {
  botUsername?: string;
  botUserId?: string;
}

export class ChatIdentityInstructionProvider extends BaseInstructionProvider {
  // Widened to `string` deliberately: an inferred literal type would make the
  // property invariant and block a subclass from naming itself.
  readonly name: string = "chat-identity";
  readonly priority = 20;

  constructor(
    protected readonly manager: ChatInstanceManager,
    protected readonly platform: string
  ) {
    super();
  }

  /**
   * Resolve this agent's bot identity on this platform.
   *
   * Requires an org and runs the read inside it: `listConnections` is
   * agent-scoped, and an agent id can exist in many orgs, so an unscoped read
   * would return ANOTHER tenant's newest connection for a shared agent id and
   * leak its botUsername/botUserId. (`InstructionService` also gates providers
   * out when `orgScoped === false`; this is the belt to that suspenders.)
   */
  protected async resolveIdentity(
    context: InstructionContext
  ): Promise<ChatBotIdentity | null> {
    if (!context.organizationId) return null;
    const connections = await orgContext.run(
      { organizationId: context.organizationId },
      () =>
        this.manager.listConnections({
          platform: this.platform,
          agentId: context.agentId,
        })
    );
    const connection = connections[0];
    if (!connection) return null;

    return {
      botUsername: connection.metadata?.botUsername as string | undefined,
      botUserId: connection.metadata?.botUserId as string | undefined,
    };
  }

  protected async buildInstructions(
    context: InstructionContext
  ): Promise<string> {
    // Tenant safety gate, and the ONLY reason to emit nothing: `resolveIdentity`
    // would otherwise read another org's connection for a shared agent id.
    if (!context.organizationId) return "";

    // Identity is best-effort — `Adapter.botUserId` is optional in the Chat SDK
    // and some platforms configure no handle at all — but the participation
    // framing is the part that actually fixes the observer voice, so it must NOT
    // be conditional on resolving a handle. Emit it either way.
    const identity = await this.resolveIdentity(context);
    return this.renderIdentity(identity ?? {});
  }

  /**
   * The participation framing. Split out so a platform provider can append its
   * own quirks (Slack's mention syntax) without restating any of this.
   */
  protected renderIdentity(identity: ChatBotIdentity): string {
    const label = platformLabel(this.platform);
    const lines: string[] = [`**${label} identity:**`];

    if (identity.botUsername && identity.botUserId) {
      lines.push(
        `- You are reachable in ${label} as \`@${identity.botUsername}\` (user ID \`${identity.botUserId}\`).`
      );
    } else if (identity.botUsername) {
      lines.push(
        `- You are reachable in ${label} as \`@${identity.botUsername}\`.`
      );
    } else if (identity.botUserId) {
      lines.push(`- Your ${label} user ID is \`${identity.botUserId}\`.`);
    }

    // The load-bearing part. Identity alone still leaves "am I a participant or
    // an observer?" open, and the agent's own identity markdown argues for
    // observer by describing the principal in the third person.
    lines.push(
      "- You are a participant in this conversation, not an observer of it. Messages delivered to you are addressed to you by the person you are talking with.",
      "- Reply to that person directly, in the second person. Do not describe them in the third person, do not narrate what they said back to them, and do not ask anyone else how you should respond — there is no operator reading this conversation."
    );

    return lines.join("\n");
  }
}

