test("EVERY registered platform resolves a provider — enumerated, not sampled", () => {
  // Guards the whole class rather than the one platform that surfaced the
  // bug: a platform added to PLATFORM_REGISTRY later inherits the framing,
  // and this fails if someone reintroduces an opt-in conditional.
  const platforms = Object.keys(PLATFORM_REGISTRY);
  expect(platforms.length).toBeGreaterThanOrEqual(6);

  const missing = platforms.filter(
    (p) =>
      !(
        adapterFor(p).getInstructionProvider?.() instanceof
        ChatIdentityInstructionProvider
      )
  );

  expect(missing).toEqual([]);
});

