1	/**
2	 * Platform-agnostic chat identity.
3	 *
4	 * An agent reached over a chat connection needs two facts that nothing else in
5	 * the prompt supplies: WHO it is in that conversation, and that the messages it
6	 * receives are addressed TO it. Without them the agent has only its
7	 * identity/soul markdown, which describes the principal in the third person
8	 * ("you work on the user's data on their behalf") and never says the person
9	 * currently typing IS that principal. A capable model resolves that gap the
10	 * wrong way: it treats the inbound message as observed conversation about a
11	 * third party and narrates it back — "Burak sent a message … how would you like
12	 * to respond?" — addressing an operator who does not exist.
13	 *
14	 * Slack never showed this because `SlackInstructionProvider` happened to state
15	 * "You are reachable in Slack as `@x`", which is enough to establish
16	 * participation. Every platform that did not declare an instruction provider
17	 * (Telegram, WhatsApp, …) got nothing. This provider is the default for all of
18	 * them, so the framing is a property of being a chat connection rather than
19	 * something each platform re-derives.
20	 *
21	 * PROMPT-CACHE CONTRACT — read before adding a line here.
22	 * These instructions sit at the FRONT of `gatewayInstructions`
23	 * (`session-context.ts`), and the Gemini/OpenAI-completions path has no
24	 * explicit cache breakpoints: reuse is longest-common-prefix only. Everything
25	 * emitted here must therefore be CONNECTION-scoped (platform, bot handle, bot
26	 * id) — values that are constant for the life of the connection, so every
27	 * conversation on it shares one prefix. Never interpolate anything
28	 * CONVERSATION-scoped (the sender's name, channel/chat id, message text,
29	 * timestamps): that hands every new conversation a unique prefix and forfeits
30	 * the cache for all of them.
31	 */
32	import { BaseInstructionProvider, type InstructionContext } from "@lobu/core";
33	import { orgContext } from "../../lobu/stores/org-context.js";
34	import type { ChatInstanceManager } from "./chat-instance-manager.js";
35	
36	/** Human-facing platform label; falls back to the raw key. */
37	const PLATFORM_LABELS: Record<string, string> = {
38	  slack: "Slack",
39	  telegram: "Telegram",
40	  whatsapp: "WhatsApp",
41	  discord: "Discord",
42	  teams: "Microsoft Teams",
43	  gchat: "Google Chat",
44	};
45	
46	export function platformLabel(platform: string): string {
47	  return PLATFORM_LABELS[platform] ?? platform;
48	}
49	
50	export interface ChatBotIdentity {
51	  botUsername?: string;
52	  botUserId?: string;
53	}
54	
55	export class ChatIdentityInstructionProvider extends BaseInstructionProvider {
56	  // Widened to `string` deliberately: an inferred literal type would make the
57	  // property invariant and block a subclass from naming itself.
58	  readonly name: string = "chat-identity";
59	  readonly priority = 20;
60	
61	  constructor(
62	    protected readonly manager: ChatInstanceManager,
63	    protected readonly platform: string
64	  ) {
65	    super();
66	  }
67	
68	  /**
69	   * Resolve this agent's bot identity on this platform.
70	   *
71	   * Requires an org and runs the read inside it: `listConnections` is
72	   * agent-scoped, and an agent id can exist in many orgs, so an unscoped read
73	   * would return ANOTHER tenant's newest connection for a shared agent id and
74	   * leak its botUsername/botUserId. (`InstructionService` also gates providers
75	   * out when `orgScoped === false`; this is the belt to that suspenders.)
76	   */
77	  protected async resolveIdentity(
78	    context: InstructionContext
79	  ): Promise<ChatBotIdentity | null> {
80	    if (!context.organizationId) return null;
81	    const connection = await orgContext.run(
82	      { organizationId: context.organizationId },
83	      async () => {
84	        if (context.connectionId) {
85	          return this.manager.getConnection(context.connectionId);
86	        }
87	        const connections = await this.manager.listConnections({
88	          platform: this.platform,
89	          agentId: context.agentId,
90	        });
91	        return connections[0] ?? null;
92	      }
93	    );
94	    if (!connection) return null;
95	
96	    return {
97	      botUsername: connection.metadata?.botUsername as string | undefined,
98	      botUserId: connection.metadata?.botUserId as string | undefined,
99	    };
100	  }
101	
102	  protected async buildInstructions(
103	    context: InstructionContext
104	  ): Promise<string> {
105	    // Tenant safety gate, and the ONLY reason to emit nothing: `resolveIdentity`
106	    // would otherwise read another org's connection for a shared agent id.
107	    if (!context.organizationId) return "";
108	
109	    // Identity is best-effort — `Adapter.botUserId` is optional in the Chat SDK
110	    // and some platforms configure no handle at all — but the participation
111	    // framing is the part that actually fixes the observer voice, so it must NOT
112	    // be conditional on resolving a handle. Emit it either way.
113	    const identity = await this.resolveIdentity(context);
114	    return this.renderIdentity(identity ?? {});
115	  }
116	
117	  /**
118	   * The participation framing. Split out so a platform provider can append its
119	   * own quirks (Slack's mention syntax) without restating any of this.
120	   */
121	  protected renderIdentity(identity: ChatBotIdentity): string {
122	    const label = platformLabel(this.platform);
123	    const lines: string[] = [`**${label} identity:**`];
124	
125	    if (identity.botUsername && identity.botUserId) {
126	      lines.push(
127	        `- You are reachable in ${label} as \`@${identity.botUsername}\` (user ID \`${identity.botUserId}\`).`
128	      );
129	    } else if (identity.botUsername) {
130	      lines.push(
131	        `- You are reachable in ${label} as \`@${identity.botUsername}\`.`
132	      );
133	    } else if (identity.botUserId) {
134	      lines.push(`- Your ${label} user ID is \`${identity.botUserId}\`.`);
135	    } else {
136	      // No handle configured for this platform. Still say where we are — the
137	      // framing below reads as a non-sequitur without it.
138	      lines.push(`- You are reachable in this ${label} conversation.`);
139	    }
140	
141	    // The load-bearing part. Identity alone still leaves "am I a participant or
142	    // an observer?" open, and the agent's own identity markdown argues for
143	    // observer by describing the principal in the third person.
144	    lines.push(
145	      "- You are a participant in this conversation, not an observer of it. Messages delivered to you are addressed to you by the person you are talking with.",
146	      "- Reply to that person directly, in the second person. Do not describe them in the third person, do not narrate what they said back to them, and do not ask anyone else how you should respond — there is no operator reading this conversation."
147	    );
148	
149	    return lines.join("\n");
150	  }
151	}

