/**
 * Resolve this agent's bot identity on this platform.
 *
 * Requires an org and runs the read INSIDE it: both reads are agent- or
 * id-scoped and rely on the ambient org (`tryGetOrgId`), so an unscoped read
 * would return ANOTHER tenant's connection for a shared agent id and leak its
 * botUsername/botUserId. (`InstructionService` also gates providers out when
 * `orgScoped === false`; this is the belt to that suspenders.)
 *
 * `connectionId` comes from the signed token and names the exact connection
 * this turn belongs to, so it is preferred. It is NOT guaranteed: the gateway
 * treats an absent connectionId as "not a chat run" (see `gateway/index.ts`),
 * and Slack resolved its identity by agent+platform long before this field was
 * plumbed through. Falling back to that read keeps a turn without the field
 * from silently losing its handle — which for Slack would also drop the
 * `<@U…>` mention guidance layered on top.
 */
protected async resolveIdentity(
  context: InstructionContext
): Promise<ChatBotIdentity | null> {
  const { organizationId, connectionId } = context;
  if (!organizationId) return null;
  const connection = await orgContext.run({ organizationId }, async () => {
    if (connectionId) {
      const exact = await this.manager.getConnection(connectionId);
      if (exact) return exact;
    }
    const connections = await this.manager.listConnections({
      platform: this.platform,
      agentId: context.agentId,
    });
    return connections[0] ?? null;
  });
  if (!connection) return null;

