export default async (ctx, client) => {
  const c = await client.connections.get({ connection_id: 432 });
  return { name: c?.name, kind: c?.connector_key ?? c?.kind, status: c?.status };
};

export default async (ctx, client) => {
  const list = await client.connections.list({ limit: 100 });
  const arr = Array.isArray(list) ? list : (list?.data ?? list?.items ?? []);
  return arr.filter(c => /browser|chrome|owletto|device/i.test(JSON.stringify(c).slice(0,600)))
            .map(c => ({ id: c.id, slug: c.slug, key: c.connector_key, status: c.status, device: c.device_worker_id }));
};

export default async (ctx, client) => {
  const def = await client.connectors.get({ connector_key: "chrome" });
  const ops = def?.operations ?? def?.actions ?? def?.tools ?? null;
  return { keys: Object.keys(def ?? {}), ops: ops && (Array.isArray(ops) ? ops.map(o => o.key ?? o.name) : Object.keys(ops)) };
};

export default async (ctx, client) => {
  const r = await client.operations.listAvailable({ connection_id: 432 });
  const arr = Array.isArray(r) ? r : (r?.operations ?? r?.data ?? []);
  return arr.map(o => o.operation_key ?? o.key ?? o.name);
};

export default async (ctx, client) => {
  const nav = await client.operations.execute({
    connection_id: 432,
    operation_key: "navigate",
    input: { url: "https://web.telegram.org/k/#@burembalobubot" },
  });
  await ctx.sleep(6000);
  const focus = await client.operations.execute({
    connection_id: 432, operation_key: "focus_tab", input: {},
  });
  return { nav, focus };
};

