export default async (ctx, client) => {
  const r = await client.operations.listAvailable({ connection_id: 432 });
  const arr = Array.isArray(r) ? r : (r?.operations ?? r?.data ?? []);
  return arr.filter(o => ["type_ref","click_ref"].includes(o.operation_key ?? o.key ?? o.name));
};

export default async (ctx, client) => {
  const TAB = 558570587;
  const r = await client.operations.execute({
    connection_id: 432, operation_key: "get_accessibility_tree", input: { tab_id: TAB },
  });
  const s = JSON.stringify(r.output ?? r);
  return { epoch: (s.match(/"document_epoch":\s*(\d+)/) || [])[1], len: s.length,
           hits: s.split(/[{}]/).filter(x => /message|send|composer|textbox/i.test(x)).slice(0, 40) };
};

export default async (ctx, client) => {
  const TAB = 558570587;
  const r = await client.operations.execute({
    connection_id: 432, operation_key: "get_accessibility_tree", input: { tab_id: TAB },
  });
  return JSON.stringify(r.output ?? r).slice(0, 2800);
};

export default async (ctx, client) => {
  const TAB = 558570587, EPOCH = 2;
  const t = await client.operations.execute({
    connection_id: 432, operation_key: "type_ref",
    input: { tab_id: TAB, ref: { ref_id: 21, document_epoch: EPOCH }, text: "hey", clear_first: true },
  });
  await ctx.sleep(1200);
  const c = await client.operations.execute({
    connection_id: 432, operation_key: "click_ref",
    input: { tab_id: TAB, ref: { ref_id: 23, document_epoch: EPOCH } },
  });
  await ctx.sleep(2500);
  const probe = await client.operations.execute({
    connection_id: 432, operation_key: "evaluate",
    input: { tab_id: TAB, expression: `[...document.querySelectorAll('.bubble .message')].slice(-2).map(n=>n.innerText.slice(0,160))` },
  });
  return { typed: t.status, clicked: c.status, probe: probe.output?.value };
};

export default async (ctx, client) => {
  const TAB = 558570587, EPOCH = 2;
