    await client.operations.execute({ connection_id: 432, operation_key: "type_ref",
      input: { tab_id: TAB, ref: { ref_id: 21, document_epoch: EPOCH }, text, clear_first: true } });
    await ctx.sleep(1000);
    await client.operations.execute({ connection_id: 432, operation_key: "click_ref",
      input: { tab_id: TAB, ref: { ref_id: 23, document_epoch: EPOCH } });
  };
  await ctx.sleep(20000);
  await send("what can you do?");
  await ctx.sleep(25000);
  await send("good morning");
  await ctx.sleep(25000);
  await send("who are you?");
  await ctx.sleep(25000);
  const probe = await client.operations.execute({
    connection_id: 432, operation_key: "evaluate",
    input: { tab_id: TAB, expression: `[...document.querySelectorAll('.bubble .message')].slice(-10).map(n=>n.innerText.slice(0,260))` },
  });
  return probe.output?.value;
};

