  const a = await client.agents.get({ agent_id: "personal-agent" });
  return {
    keys: Object.keys(a ?? {}),
    name: a?.name,
    identity: (a?.identityMd ?? a?.identity_md ?? a?.identity ?? "")?.slice(0, 900),
    soulLen: (a?.soulMd ?? a?.soul_md ?? a?.soul ?? "").length,
  };
};

export default async (ctx, client) => {
  const r = await client.agents.get({ agent_id: "personal-agent" });
  const a = r.agent ?? r;
  return {
    keys: Object.keys(a ?? {}),
    identityLen: (a?.identityMd ?? "").length,
    soulLen: (a?.soulMd ?? "").length,
    identity: (a?.identityMd ?? "").slice(0, 700),
  };
};

