export default async (ctx, client) => {
  const TAB = 558570587, EPOCH = 2;
  await client.operations.execute({ connection_id: 432, operation_key: "type_ref",
    input: { tab_id: TAB, ref: { ref_id: 21, document_epoch: EPOCH }, text: "what do you track for me?", clear_first: true } });
  await ctx.sleep(1000);
  await client.operations.execute({ connection_id: 432, operation_key: "click_ref",
    input: { tab_id: TAB, ref: { ref_id: 23, document_epoch: EPOCH } } });
  await ctx.sleep(30000);
  const p = await client.operations.execute({ connection_id: 432, operation_key: "evaluate",
    input: { tab_id: TAB, expression: `[...document.querySelectorAll('.bubble .message')].slice(-3).map(n=>n.innerText.slice(0,400))` } });
  return p.output?.value;
};

export default async (ctx, client) => {
  const nav = await client.operations.execute({ connection_id: 432, operation_key: "navigate",
    input: { url: "https://web.telegram.org/k/#@burembalobubot" } });
  const TAB = nav.output.tab_id;
  await ctx.sleep(6000);
  await client.operations.execute({ connection_id: 432, operation_key: "focus_tab", input: { tab_id: TAB } });
  await ctx.sleep(2000);
  const tree = await client.operations.execute({ connection_id: 432, operation_key: "get_accessibility_tree", input: { tab_id: TAB } });
  const nodes = tree.output.tree ?? [];
  const composer = nodes.filter(n => n.bbox && n.bbox.y > 700 && n.bbox.w > 300 && n.tag === "div");
  const buttons = nodes.filter(n => n.tag === "button" && n.bbox && n.bbox.y > 780);
  return { TAB, epoch: tree.output.document_epoch, composer, buttons };
};

