  await ctx.sleep(1200);
  await client.operations.execute({ connection_id: 432, operation_key: "click_ref",
    input: { tab_id: TAB, ref: { ref_id: 22, document_epoch: EPOCH } } });
  await ctx.sleep(35000);
  const p = await client.operations.execute({ connection_id: 432, operation_key: "evaluate",
    input: { tab_id: TAB, expression: `[...document.querySelectorAll('.bubble .message')].slice(-3).map(n=>n.innerText.slice(0,500))` } });
  return p.output?.value;
};

