/**
 * The web origin an agent can build Lobu links against, derived from the same
 * `DISPATCHER_URL` the worker already uses to reach the gateway.
 *
 * Every server-side URL builder composes admin routes as
 * `<webOrigin>/<orgSlug>/...` and strips a trailing `/lobu` first, because in
 * embedded mode the gateway is mounted under `/lobu` while those routes are
 * not. This mirrors that strip so the agent and the server agree on the origin;
 * without it every link the agent writes would 404 on embedded deployments.
 *
 * The org slug is deliberately NOT resolved here — the agent reads it with
 * `client.organizations.current()` when it actually needs a link, which keeps a
 * per-org lookup out of the hot path of every turn.
 */
export function resolveWebOrigin(
  dispatcherUrl: string | undefined = process.env.DISPATCHER_URL
): string | undefined {
  if (!dispatcherUrl) return undefined;
  const trimmed = dispatcherUrl.trim();
  if (!trimmed) return undefined;
  try {
    // Parse rather than regex: a malformed env value should yield no line at
    // all, not a mangled origin the agent would paste into a reply.
    const parsed = new URL(trimmed);
    const path = parsed.pathname.replace(/\/+$/, "").replace(/\/lobu$/, "");
    return `${parsed.origin}${path}`;
  } catch {
    return undefined;
  }
}

