92	    const out = buildRunContextBlock({
93	      platform: "slack",
94	      channelId: "C1",
95	      platformMetadata: { senderDisplayName: "x".repeat(5000) },
96	    });
97	    const line = out.split("\n").find((l) => l.startsWith("- Triggered by:"))!;
98	    // "- Triggered by: " prefix + <=200 chars.
99	    expect(line.length).toBeLessThanOrEqual("- Triggered by: ".length + 200);
100	  });
101	
102	  test("renders nothing on the web (api) surface", () => {
103	    // On `api` the user is looking at the web chat, so "Platform: api" and the
104	    // synthetic "Channel: api_<userId>" name orient nobody — there is no other
