});

describe("resolveWebOrigin", () => {
  test("passes a plain gateway origin through", () => {
    expect(resolveWebOrigin("https://app.lobu.ai")).toBe("https://app.lobu.ai");
  });

  test("strips the embedded-mode /lobu suffix", () => {
    // Admin routes live at the web origin, NOT under the gateway's /lobu mount.
    // Without this strip every link the agent writes would 404 when embedded.
    expect(resolveWebOrigin("https://acme.example/lobu")).toBe(
      "https://acme.example"
    );
  });

  test("strips a trailing slash before the /lobu check", () => {
    expect(resolveWebOrigin("https://acme.example/lobu/")).toBe(
      "https://acme.example"
    );
  });

  test("keeps a non-/lobu base path", () => {
    expect(resolveWebOrigin("https://acme.example/lobu-staging")).toBe(
      "https://acme.example/lobu-staging"
    );
  });

  test("yields nothing for missing or malformed values", () => {
    // A mangled origin pasted into a reply is worse than no line at all.
    expect(resolveWebOrigin(undefined)).toBeUndefined();
    expect(resolveWebOrigin("   ")).toBeUndefined();
    expect(resolveWebOrigin("not a url")).toBeUndefined();
  });
});

