input.old_string:
/**
 * The web origin an agent can compose user-openable Lobu links against:
 * `<webOrigin>/<orgSlug>/agents/<agentId>/conversations/<id>` and friends.
 *
 * Two things this must get right, both mirroring the server-side URL
 * builders. The `/lobu` suffix is stripped because in embedded mode the
 * gateway is mounted under it while the admin routes linked to are not — a
 * link built on the unstripped base 404s. And a `publicGatewayUrl` that is
 * not a parseable absolute URL yields `undefined` rather than a mangled
 * string, so the agent omits the line instead of pasting a broken origin
 * into a reply.
 */
private getPublicWebOrigin(): string | undefined {
  try {
    const parsed = new URL(this.publicGatewayUrl);
    const path = parsed.pathname.replace(/\/+$/, "").replace(/\/lobu$/, "");
    return `${parsed.origin}${path}`;
  } catch {
    return undefined;
  }
}

