					(budget > 0 ? ` after ${budget + 1} attempt(s)` : "") +
					". Check that the assigned agent has the lobu-memory MCP attached and that query_sdk / " +
					"run_sdk tools are approved for it."
			);
			resolved++;
			continue;
		}

