/**
 * A Behavior run that fails terminally MUST advance `next_run_at`.
 *
 * Observed in prod 2026-07-29: Behavior 5 ("hourly-task-collaborator",
 * `cron: 0 * * * *`) produced 296 failed runs in 5 hours — one per minute — with
 * `next_run_at` frozen at 2026-07-27T22:00:00Z, 44 hours stale. 1,440 wasted
 * runs/day against a provider returning 429.
 *
 * Cause: there are TWO terminal-failure paths for a Behavior run.
 * `watchers/automation.ts:failWatcherRun` advances the cron cursor;
 * `watchers/run-completion.ts:markWatcherRunFailed` did not. The dispatch loop
 * selects `next_run_at <= now()`, so a run failing through the second path is
 * re-materialized on the very next tick, forever. Both of its call sites are
 * ordinary failures, not edge cases:
 *   - the agent turn returned an error (`!result.ok`) — the 429 case
 *   - the agent finished without calling `complete_window` past its nudge budget
 *
 * `min_cooldown_seconds` would have capped the blast radius, but it is stored
 * and surfaced without ever being read by scheduling code — no second guard.
 */
import { beforeAll, describe, expect, it } from "vitest";
import type { DbClient } from "../../../db/client";
import { getDb } from "../../../db/client";
import { resolveWatcherRunsByMessageIds } from "../../../watchers/run-completion";
import { getTestDb } from "../../setup/test-db";
import { createTestAgent, createTestEntity } from "../../setup/test-fixtures";
import { TestWorkspace } from "../../setup/test-mcp-client";

async function createDueWatcherWithDispatchedRun(opts: {
  slug: string;
  messageId: string;
  nudgeCount?: number;
}) {
  const sql = getTestDb();
  const dbClient = sql as unknown as DbClient;
  const workspace = await TestWorkspace.create({
    name: `Failed Run Advance ${opts.slug}`,
  });
  const entity = await createTestEntity({
    name: "Advance Entity",
    organization_id: workspace.org.id,
    created_by: workspace.users.owner.id,
  });
  const agent = await createTestAgent({
    organizationId: workspace.org.id,
    ownerUserId: workspace.users.owner.id,
    agentId: `advance-agent-${opts.slug}`,
    name: "Advance Agent",
  });

  const behavior = (await workspace.owner.behaviors.create({
    entity_id: entity.id,
    slug: opts.slug,
    name: "Advance Behavior",
    prompt: "Summarize content for {{entities}}.",
    triggers: [
      {
        kind: "schedule",
        cron: "0 * * * *",
        execution: "window",
        active_run: "coalesce",
        skip_if_unchanged: false,
      },
    ],
    agent_id: agent.agentId,
  })) as { behavior_id: string };
  const watcherId = Number(behavior.behavior_id);

  // The prod shape: the cursor is stale, so the dispatch loop keeps selecting it.
  const staleCursor = new Date(Date.now() - 44 * 60 * 60 * 1000);
  await sql`
    UPDATE watchers SET next_run_at = ${staleCursor}::timestamptz
    WHERE id = ${watcherId}
  `;

  const [run] = await sql`
    INSERT INTO runs (organization_id, run_type, watcher_id, status,
                      dispatched_message_id, approved_input)
    VALUES (${workspace.org.id}, 'behavior', ${watcherId}, 'running',
            ${opts.messageId},
            ${sql.json({ finalize_nudge_count: opts.nudgeCount ?? 99 })})
    RETURNING id
  `;

  return {
    sql,
    dbClient,
    watcherId,
    runId: Number(run.id),
    staleCursor,
  };
}

async function cursorOf(watcherId: number): Promise<Date> {
  const sql = getTestDb();
  const [row] =
    await sql`SELECT next_run_at FROM watchers WHERE id = ${watcherId}`;
  return new Date(row.next_run_at as string);
}

describe("a terminally failed Behavior run advances next_run_at", () => {
  beforeAll(() => {
    getDb();
  });

  it("advances the cursor when the agent turn returns an error (the 429 case)", async () => {
    const { watcherId, runId, staleCursor } =
      await createDueWatcherWithDispatchedRun({
        slug: "advance-on-turn-error",
        messageId: "msg-turn-error",
      });

    await resolveWatcherRunsByMessageIds(
      ["msg-turn-error"],
      {
        ok: false,
        error:
          "z.ai returned an error:\n429 Weekly/Monthly Limit Exhausted. Your limit will reset at 2026-07-31 04:32:47",
      }
    );

    const sql = getTestDb();
    const [run] = await sql`SELECT status FROM runs WHERE id = ${runId}`;
    expect(run.status).toBe("failed");

    // The whole point: without this the dispatch loop re-fires every tick.
    const after = await cursorOf(watcherId);
    expect(after.getTime()).toBeGreaterThan(staleCursor.getTime());
    expect(after.getTime()).toBeGreaterThan(Date.now());
  });

  it("advances the cursor when the agent never calls complete_window", async () => {
    const { watcherId, runId, staleCursor } =
      await createDueWatcherWithDispatchedRun({
        slug: "advance-on-finalize-miss",
        messageId: "msg-finalize-miss",
        // Past the nudge budget, so this resolves terminally rather than requeuing.
        nudgeCount: 99,
      });

    await resolveWatcherRunsByMessageIds(["msg-finalize-miss"], { ok: true });

    const sql = getTestDb();
    const [run] = await sql`SELECT status FROM runs WHERE id = ${runId}`;
    expect(run.status).toBe("failed");

    const after = await cursorOf(watcherId);
    expect(after.getTime()).toBeGreaterThan(staleCursor.getTime());
    expect(after.getTime()).toBeGreaterThan(Date.now());
  });

  it("leaves the cursor alone on success — completeWindow owns that advance", async () => {
    // Guard the fix from over-reaching: this path must not double-advance, or a
    // successful run would skip its next slot.
    const { watcherId, staleCursor } = await createDueWatcherWithDispatchedRun({
      slug: "advance-not-on-success",
      messageId: "msg-success",
      nudgeCount: 0,
    });

    // ok:true with a nudge budget remaining requeues rather than failing, so the
    // cursor must be untouched by this module.
    await resolveWatcherRunsByMessageIds(["msg-success"], { ok: true });

    const after = await cursorOf(watcherId);
    expect(after.getTime()).toBe(staleCursor.getTime());
  });
});

