export default async (ctx, client) => {
  const nav = await client.operations.execute({ connection_id: 432, operation_key: "navigate",
    input: { url: "https://web.telegram.org/k/#@burembalobubot" } });
  const TAB = nav.output.tab_id;
  await ctx.sleep(7000);
  await client.operations.execute({ connection_id: 432, operation_key: "focus_tab", input: { tab_id: TAB } });
  await ctx.sleep(2000);
  const tree = await client.operations.execute({ connection_id: 432, operation_key: "get_accessibility_tree", input: { tab_id: TAB } });
  const nodes = tree.output.tree ?? [];
  const EPOCH = tree.output.document_epoch;
  const composer = nodes.find(n => n.tag === "div" && n.bbox && n.bbox.y > 700 && n.bbox.w > 300);
  const btns = nodes.filter(n => n.tag === "button" && n.bbox && n.bbox.y > 780).sort((a,b)=>b.bbox.x-a.bbox.x);
  const q = "Answer plainly, no tools: what is your agent id, this conversation id, and your Lobu base URL? Say unknown for anything you don't have.";
  await client.operations.execute({ connection_id: 432, operation_key: "type_ref",
    input: { tab_id: TAB, ref: { ref_id: composer.ref_id, document_epoch: EPOCH }, text: q, clear_first: true } });
  await ctx.sleep(1200);
  await client.operations.execute({ connection_id: 432, operation_key: "click_ref",
    input: { tab_id: TAB, ref: { ref_id: btns[0].ref_id, document_epoch: EPOCH } } });
  return { TAB, sent: q };
};

export default async (ctx, client) => {
  const TAB = 558570613;
  const p = await client.operations.execute({ connection_id: 432, operation_key: "evaluate",
    input: { tab_id: TAB, expression: `(() => {
      const c = document.querySelector('.input-message-input[contenteditable="true"]');
      return { composerText: c ? c.innerText.slice(0,120) : null,
               last: [...document.querySelectorAll('.bubble .message')].slice(-2).map(n=>n.innerText.slice(0,120)) };
    })()` } });
  return p.output?.value;
};

