export default async (ctx, client) => {
  const before = await client.behaviors.get({ behavior_id: 5 });
  const b = before.behavior ?? before;
  const current = b.execution_config ?? {};
  const updated = { ...current, model: "gemini/gemini-2.5-pro" };
  const res = await client.behaviors.update({ behavior_id: 5, execution_config: updated });
  const after = await client.behaviors.get({ behavior_id: 5 });
  return {
    before_execution_config: current,
    after_execution_config: (after.behavior ?? after).execution_config,
    update_status: res?.status ?? res?.action ?? "ok",
  };
};

export default async (ctx, client) => {
  // Restore the full config I read as {} because behaviors.get does not expose
  // execution_config — the original values came from the DB row.
  const res = await client.behaviors.update({
    behavior_id: 5,
    execution_config: {
      model: "gemini/gemini-2.5-pro",
      permission_mode: "dontAsk",
      timeout_seconds: 600,
    },
  });
  return { update: res?.action ?? res };
};

