onError: async (watcher, error) => {
	logger.error(
		{ error, watcherId: watcher.id },
		"[watcher-automation] Failed to materialize due watcher run"
	);
	// Don't leave next_run_at in the past — that would re-select this watcher
	// on every 60s tick. Push it forward per the watcher's cron schedule.
	//
	// Contained deliberately. `advanceWatcherSchedule` propagates so its
	// transactional callers can roll back a durable transition, but this is
	// the materializer's per-item error hook and `materializeDueItems` does
	// NOT guard its own `onError` call. A throw here escapes the per-item
	// loop and aborts the whole tick, so ONE Behavior with an unparseable
	// cron would stop every other org's Behaviors from materializing. A
	// missed advance costs this watcher a hot loop; a thrown one costs
	// everyone their tick.
	try {
		await advanceWatcherSchedule(sql, watcher.id);
	} catch (advanceError) {
		logger.error(
			{ error: advanceError, watcherId: watcher.id },
			"[watcher-automation] Failed to advance next_run_at after a materialize error — this watcher will re-select next tick"
		);
	}
},

