82	describe("a terminally failed Behavior run advances next_run_at", () => {
83	  it("advances the cursor when the agent turn returns an error", async () => {
84	    const { watcherId, runId, staleCursor } =
85	      await createDueWatcherWithDispatchedRun({
86	        slug: "advance-on-turn-error",
87	        messageId: "msg-turn-error",
88	      });
89	
90	    await resolveWatcherRunsByMessageIds(
