95	      }
96	    );
97	
98	    const sql = getTestDb();
99	    const [run] = await sql`SELECT status FROM runs WHERE id = ${runId}`;
100	    expect(run.status).toBe("failed");
101	
102	    const after = await cursorOf(watcherId);
103	    expect(after.getTime()).toBeGreaterThan(staleCursor.getTime());
104	    expect(after.getTime()).toBeGreaterThan(Date.now());
105	  });
106	
107	  it("advances the cursor when the agent never calls complete_window", async () => {
108	    const { watcherId, runId, staleCursor } =
109	      await createDueWatcherWithDispatchedRun({
110	        slug: "advance-on-finalize-miss",
111	        messageId: "msg-finalize-miss",
112	        // Past the nudge budget, so this resolves terminally rather than requeuing.
113	        nudgeCount: 99,
114	      });
115	
116	    await resolveWatcherRunsByMessageIds(["msg-finalize-miss"], { ok: true });
117	
118	    const sql = getTestDb();
119	    const [run] = await sql`SELECT status FROM runs WHERE id = ${runId}`;
120	    expect(run.status).toBe("failed");
121	
122	    const after = await cursorOf(watcherId);
123	    expect(after.getTime()).toBeGreaterThan(staleCursor.getTime());
124	    expect(after.getTime()).toBeGreaterThan(Date.now());
125	  });
126	
127	  it("does NOT advance for an event-dispatched run", async () => {
128	    // Event delivery is independent of the cron cursor. If a failing event
129	    // delivery advanced it, that Behavior would silently skip its next
130	    // scheduled activation — a missed run, caused by an unrelated failure.
131	    // `failWatcherRun` carves this out; without the same carve-out here the two
132	    // failure paths would disagree about what a failure means.
133	    const { watcherId, runId, staleCursor } =
134	      await createDueWatcherWithDispatchedRun({
