146	    const [run] = await sql`SELECT status FROM runs WHERE id = ${runId}`;
147	    expect(run.status).toBe("failed");
148	
149	    const after = await cursorOf(watcherId);
150	    expect(after.getTime()).toBe(staleCursor.getTime());
151	  });
152	
153	  it("leaves the cursor alone while a finalize nudge requeues the run", async () => {
154	    const { watcherId, staleCursor } = await createDueWatcherWithDispatchedRun({
155	      slug: "no-advance-on-requeue",
156	      messageId: "msg-requeue",
157	      nudgeCount: 0,
158	    });
