166	  it("one Behavior with an unparseable cron cannot abort the whole tick", async () => {
167	    // `advanceWatcherSchedule` propagates so transactional callers can roll
168	    // back. But `materializeDueItems` does NOT guard its own `onError` call, so
169	    // an unguarded throw in that hook escapes the per-item loop and kills the
170	    // tick — every other ORG's Behaviors stop materializing behind one corrupt
171	    // row. This asserts the containment at that hook.
172	    const { sql, watcherId } = await createDueWatcherWithDispatchedRun({
173	      slug: "corrupt-cron-tick-isolation",
174	      messageId: "msg-corrupt-cron",
175	    });
