177	    await sql`DELETE FROM runs WHERE watcher_id = ${watcherId}`;
178	    await sql`
179	      UPDATE watchers SET schedule = 'not-a-cron' WHERE id = ${watcherId}
180	    `;
181	
182	    // Must resolve, not reject: a tick that throws takes every tenant with it.
183	    await expect(materializeDueWatcherRuns()).resolves.toBeDefined();
184	  });
185	
186	  it("rolls back the failure transition when the cursor cannot advance", async () => {
187	    const { sql, watcherId, runId } =
188	      await createDueWatcherWithDispatchedRun({
189	        slug: "rollback-on-cursor-error",
190	        messageId: "msg-invalid-schedule",
191	      });
