export default async (ctx, client) => {
  const r = await client.knowledge.read({
    behavior_id: 5,
    since: "2026-07-29T17:00:00Z",
    until: "2026-07-29T18:00:00Z",
    template_version_id: 207,
  });
  const sizes = {};
  for (const [k, v] of Object.entries(r ?? {})) {
    sizes[k] = JSON.stringify(v ?? null).length;
  }
  const srcSizes = {};
  const sources = r?.sources ?? {};
  for (const [k, v] of Object.entries(sources)) {
    srcSizes[k] = { bytes: JSON.stringify(v ?? null).length, rows: Array.isArray(v) ? v.length : (Array.isArray(v?.content) ? v.content.length : null) };
  }
  return { total: JSON.stringify(r).length, topLevel: sizes, perSource: srcSizes };
};

export default async (ctx, client) => {
  const out = {};
  for (const w of [
    { label: "agent's failing call (Jul 27 day)", since: "2026-07-27", until: "2026-07-27" },
    { label: "Jul 27 06:00-12:00", since: "2026-07-27T06:00:00Z", until: "2026-07-27T12:00:00Z" },
  ]) {
    try {
      const r = await client.knowledge.read({ behavior_id: 5, since: w.since, until: w.until, template_version_id: 207 });
      const per = {};
      for (const [k, v] of Object.entries(r?.sources ?? {})) {
        per[k] = { bytes: JSON.stringify(v ?? null).length, rows: Array.isArray(v) ? v.length : null };
      }
      out[w.label] = { total: JSON.stringify(r).length, perSource: per };
    } catch (e) {
      out[w.label] = { error: String(e?.message ?? e).slice(0, 160) };
    }
  }
  return out;
};

export default async (ctx, client) => {
  const r = await client.behaviors.trigger({ behavior_id: 5 });
  return r;
};

