        WHERE id = ${watcherId}
      `;
    }
  });

  it("propagates a database error so the caller can roll back", async () => {
    // The transactional failure path is only meaningful if TRANSIENT errors
    // still surface. Parking must not swallow a dead connection.
    let queries = 0;
    const failingSql = (async () => {
      queries++;
      if (queries === 1) return [{ schedule: "0 * * * *", timezone: null }];
      throw new Error("connection terminated unexpectedly");
    }) as unknown as Parameters<typeof advanceWatcherSchedule>[0];

    await expect(advanceWatcherSchedule(failingSql, 1)).rejects.toThrow(
      /connection terminated/
    );
    expect(queries).toBe(2);
  });
});

