        })},
        NOW() + INTERVAL '1 hour'
      )
    `;

    await resolveWatcherRunsByMessageIds(["msg-gated-approval"], { ok: true });

    const [run] =
      await sql`SELECT status, error_message FROM runs WHERE id = ${runId}`;
