/**
 * Does this dispatched agent turn belong to an active Behavior configured for
 * unattended write-tool use?
 *
 * A scheduled Behavior has no human in the loop, so an MCP approval card cannot
 * be answered during the turn. `execution_config.permission_mode` is the
 * operator's Behavior-scoped declaration that the turn may proceed without it.
 */

import { type DbClient, getDb } from "../../db/client.js";
import { UNATTENDED_PERMISSION_MODES } from "../../tools/admin/behavior-execution-config.js";
import logger from "../../utils/logger.js";

interface UnattendedRunScope {
	runId: number | null | undefined;
	organizationId: string | undefined;
	agentId: string;
	conversationId: string;
}

export async function runAllowsUnattendedToolUse(
	scope: UnattendedRunScope,
	db?: DbClient,
): Promise<boolean> {
	if (scope.runId == null || !scope.organizationId) return false;

	try {
		const sql = db ?? getDb();
		const rows = await sql`
      WITH dispatch AS (
        SELECT CASE jsonb_typeof(action_input)
          WHEN 'object' THEN action_input
          WHEN 'string' THEN (action_input #>> '{}')::jsonb
          ELSE NULL
        END AS payload
        FROM runs
        WHERE id = ${scope.runId}
          AND run_type = 'chat_message'
          AND organization_id = ${scope.organizationId}
      )
      SELECT w.execution_config->>'permission_mode' AS permission_mode
      FROM dispatch d
      JOIN runs behavior_run
        ON behavior_run.id::text =
          d.payload #>> '{platformMetadata,intent,runId}'
      JOIN watchers w ON w.id = behavior_run.watcher_id
      WHERE d.payload->>'organizationId' = ${scope.organizationId}
        AND d.payload->>'agentId' = ${scope.agentId}
        AND d.payload->>'conversationId' = ${scope.conversationId}
        AND d.payload #>> '{platformMetadata,source}' = 'watcher-run'
        AND d.payload #>> '{platformMetadata,intent,kind}' = 'behavior_run'
        AND behavior_run.run_type = 'behavior'
        AND behavior_run.status = 'running'
        AND behavior_run.organization_id = ${scope.organizationId}
        AND behavior_run.watcher_id::text =
          d.payload #>> '{platformMetadata,intent,behaviorId}'
        AND behavior_run.dispatched_message_id = d.payload->>'messageId'
        AND d.payload->>'conversationId' =
          ${scope.agentId} || '_watcher_' || behavior_run.watcher_id::text ||
          '_run_' || behavior_run.id::text
        AND w.organization_id = ${scope.organizationId}
        AND w.agent_id = ${scope.agentId}
      LIMIT 1
    `;
		const mode = rows[0]?.permission_mode as string | null | undefined;
		return mode != null && UNATTENDED_PERMISSION_MODES.has(mode);
	} catch (error) {
		logger.warn(
			{ error, run_id: scope.runId },
			"[mcp] Could not read a Behavior's permission_mode — requiring tool approval",
		);
		return false;
	}
}

