/**
 * `min_cooldown_seconds` must actually debounce event-triggered Behaviors.
 *
 * The column has existed (NOT NULL DEFAULT 0) and been writable through the
 * MCP contract, `defineBehavior`, and `lobu apply` since it was added, and no
 * dispatch path ever read it. An operator who set it got no debounce at all.
 *
 * WHY ONLY THE EVENT PATH: a schedule already spaces its own firings — cron IS
 * the operator's cadence control — so a cooldown there is redundant. Worse, the
 * scheduled path would have to skip materializing a run, and `next_run_at` only
 * advances when a run reaches a terminal state (see `advanceWatcherSchedule`).
 * A suppressed scheduled firing would leave the cursor in the past and the
 * Behavior would re-select on every tick forever — exactly the hot loop #2326
 * fixed. Event activations have no cursor to strand: suppressing one simply
 * means that event does not fire this Behavior. So the cooldown belongs here
 * and only here.
 */

import { beforeAll, beforeEach, describe, expect, it } from "vitest";
import { findMatchingBehaviorActivations } from "../../../behaviors/activation";
import type { Env } from "../../../index";
import { manageBehaviors } from "../../../tools/admin/manage_behaviors";
import { initWorkspaceProvider } from "../../../workspace";
import { cleanupTestDatabase, getTestDb } from "../../setup/test-db";
import {
	createTestAgent,
	createTestConnection,
	seedOwnerContext,
} from "../../setup/test-fixtures";

interface Fixture {
	organizationId: string;
	behaviorId: number;
	signal: {
		connector_key: string;
		connection_id: string;
		event_type: string;
		label: string;
		input_text: string;
	};
}

let counter = 0;

type OwnerContext = Awaited<ReturnType<typeof seedOwnerContext>>["ctx"];

interface Workspace {
	organizationId: string;
	agentId: string;
	connectionId: string;
	ctx: OwnerContext;
}

async function behaviorWithCooldown(
	cooldownSeconds: number,
	reuse?: Workspace,
): Promise<Fixture & { workspace: Workspace }> {
	const sql = getTestDb();
	const slug = `cooldown-${++counter}`;

	let workspace: Workspace;
	if (reuse) {
		workspace = reuse;
	} else {
		const seeded = await seedOwnerContext();
		workspace = {
			organizationId: seeded.org.id,
			ctx: seeded.ctx,
			agentId: (
				await createTestAgent({
					organizationId: seeded.org.id,
					ownerUserId: seeded.user.id,
				})
			).agentId,
			connectionId: (
				await createTestConnection({
					organization_id: seeded.org.id,
					connector_key: "github",
					created_by: seeded.user.id,
				})
			).id,
		};
	}
	const { organizationId, agentId, connectionId, ctx } = workspace;

	const created = await manageBehaviors(
		{
			action: "create",
			slug,
			name: `Cooldown ${slug}`,
			prompt: "Summarize changed pull requests.",
			agent_id: agentId,
			min_cooldown_seconds: cooldownSeconds,
			triggers: [
				{
					kind: "event",
					connector_key: "github",
					connection_id: connectionId,
					event_types: ["pull_request.updated"],
					execution: "window",
					active_run: "coalesce",
					output: "silent",
				},
			],
		},
		{} as Env,
		ctx,
	);
	if (created.action !== "create" || !("behavior_id" in created)) {
		throw new Error("Behavior creation did not complete");
	}
	const behaviorId = Number(created.behavior_id);

	// Guard the fixture itself: if the contract ever stops persisting the field,
	// every assertion below would pass vacuously against cooldown 0.
	const [row] = await sql`
    SELECT min_cooldown_seconds FROM watchers WHERE id = ${behaviorId}
  `;
	expect(Number(row.min_cooldown_seconds)).toBe(cooldownSeconds);

	return {
		organizationId,
		behaviorId,
		workspace,
		signal: {
			connector_key: "github",
			connection_id: connectionId,
			event_type: "pull_request.updated",
			label: "PR changed",
			input_text: "A pull request changed.",
		},
	};
}

/** A prior firing of this Behavior, `secondsAgo` in the past. */
async function priorRun(
	fixture: Fixture,
	secondsAgo: number,
	status = "completed",
): Promise<void> {
	const sql = getTestDb();
	await sql`
    INSERT INTO runs (organization_id, run_type, watcher_id, status, created_at)
    VALUES (${fixture.organizationId}, 'behavior', ${fixture.behaviorId},
            ${status}, now() - make_interval(secs => ${secondsAgo}))
  `;
}

async function matches(fixture: Fixture): Promise<number> {
	const found = await findMatchingBehaviorActivations(
		fixture.organizationId,
		{ ...fixture.signal, delivery_id: `event:cooldown:${++counter}` },
	);
	return found.length;
}

describe("min_cooldown_seconds debounces event-triggered Behaviors", () => {
	beforeAll(async () => {
		await initWorkspaceProvider();
	});

	beforeEach(async () => {
		await cleanupTestDatabase();
	});

	it("suppresses an activation inside the cooldown window", async () => {
		const fixture = await behaviorWithCooldown(1800);
		await priorRun(fixture, 60);

		expect(await matches(fixture)).toBe(0);
	});

	it("allows an activation once the cooldown has elapsed", async () => {
		const fixture = await behaviorWithCooldown(1800);
		await priorRun(fixture, 7200);

		expect(await matches(fixture)).toBe(1);
	});

	it("allows the first activation when the Behavior has never run", async () => {
		const fixture = await behaviorWithCooldown(1800);

		expect(await matches(fixture)).toBe(1);
	});

	it("does not debounce at all when the cooldown is 0 (the default)", async () => {
		const fixture = await behaviorWithCooldown(0);
		await priorRun(fixture, 1);

		expect(await matches(fixture)).toBe(1);
	});

	it("counts a still-running firing, not just a finished one", async () => {
		// A burst that starts a run and immediately re-fires must be debounced by
		// the run it just started, otherwise the cooldown only works after the
		// first run happens to finish.
		const fixture = await behaviorWithCooldown(1800);
		await priorRun(fixture, 5, "running");

		expect(await matches(fixture)).toBe(0);
	});

	it("scopes the cooldown to one Behavior, not the whole connection", async () => {
		const cooling = await behaviorWithCooldown(1800);
		const sibling = await behaviorWithCooldown(0, cooling.workspace);
		await priorRun(cooling, 60);

		// Same signal reaches both Behaviors; only the cooling one is suppressed.
		expect(await matches(sibling)).toBe(1);
	});
});

import type { ConnectorTriggerSignal } from "@lobu/connector-sdk";
import type { BehaviorEventTrigger } from "@lobu/core/contracts/tools/manage-behaviors";
import type { DbClient } from "../db/client";
import { getDb } from "../db/client";
import { runtimeConnectionIdToSlug } from "../lobu/stores/connections-projection";
import {
  type BehaviorEventRunResult,
  createBehaviorEventRun,
} from "../runs/queue-service";
import logger from "../utils/logger";
import { dispatchPendingWatcherRuns } from "../watchers/automation";
import { matchingBehaviorTriggers } from "./event-trigger";

export interface MatchingBehaviorActivation {
  behaviorId: number;
  organizationId: string;
  agentId: string;
  deviceWorkerId: string | null;
  agentKind: string | null;
  model: string | null;
  instructions: string;
  trigger: BehaviorEventTrigger;
}

export interface BehaviorActivationResult extends BehaviorEventRunResult {
  behaviorId: number;
  trigger: BehaviorEventTrigger;
}

export interface BehaviorActivationPlan {
  signal: ConnectorTriggerSignal;
  replyTargets: MatchingBehaviorActivation[];
  backgroundTargets: MatchingBehaviorActivation[];
}

export interface RuntimeConnectionBehaviorLookup {
  connectionOrganizationId: string;
  runtimeConnectionId: string;
  signal: ConnectorTriggerSignal;
  crossOrganization?: boolean;
}

/**
 * Split matching Behaviors once, at the connector-neutral activation seam.
 * Reply targets stay with the chat transport so they retain thread history,
 * attachments, and live steering; every other target uses the durable run
 * queue. Connectors never implement this policy themselves.
 */
export function planBehaviorActivations(
  signal: ConnectorTriggerSignal,
  matches: MatchingBehaviorActivation[],
): BehaviorActivationPlan {
  const replyTargets: MatchingBehaviorActivation[] = [];
  const backgroundTargets: MatchingBehaviorActivation[] = [];
  for (const match of matches) {
    if (
      (match.trigger.execution ?? "turn") === "turn" &&
      (match.trigger.output ?? "silent") === "reply_to_source"
    ) {
      replyTargets.push(match);
    } else {
      backgroundTargets.push(match);
    }
  }
  return { signal, replyTargets, backgroundTargets };
}

/** Connector-neutral Behavior lookup used by webhooks, pollers, and chat. */
export async function findMatchingBehaviorActivations(
  organizationId: string,
  signal: ConnectorTriggerSignal,
  db: DbClient = getDb(),
  options?: { crossOrganization?: boolean },
): Promise<MatchingBehaviorActivation[]> {
  // Coarse GIN needle: kind + connector_key. When the signal carries a
  // connection_id, match that connection's triggers OR connector-wide triggers
  // (no connection_id on the trigger element). Without the connection arm the
  // org-scoped query pulled every Behavior for the connector across all
  // connections; the connection arm alone would drop connector-wide drafts.
  const baseNeedle = {
    kind: "event" as const,
    connector_key: signal.connector_key,
  };
  const organizationFilter = options?.crossOrganization
    ? db``
    : db`AND w.organization_id = ${organizationId}`;
  const connectionId = signal.connection_id;
  const triggerFilter =
    connectionId != null
      ? db`(
          w.triggers @> ${db.json([{ ...baseNeedle, connection_id: connectionId }])}::jsonb
          OR EXISTS (
            SELECT 1
            FROM jsonb_array_elements(COALESCE(w.triggers, '[]'::jsonb)) t
            WHERE t->>'kind' = 'event'
              AND t->>'connector_key' = ${signal.connector_key}
              AND t->>'connection_id' IS NULL
          )
        )`
      : db`w.triggers @> ${db.json([baseNeedle])}::jsonb`;
  const rows = await db`
		SELECT w.id, w.organization_id, w.agent_id, w.device_worker_id::text AS device_worker_id,
		       w.agent_kind, w.triggers, w.execution_config->>'model' AS model,
		       v.prompt
		FROM watchers w
		JOIN watcher_versions v ON v.id = w.current_version_id
		WHERE w.status = 'active'
		  AND w.agent_id IS NOT NULL
		  AND ${triggerFilter}
		  ${organizationFilter}
		  -- min_cooldown_seconds debounce. The column is NOT NULL DEFAULT 0, so
		  -- the guard costs nothing for the overwhelming majority of Behaviors:
		  -- at 0 the outer test short-circuits and the subquery never runs.
		  -- Counts ANY firing, not just finished ones — a burst that starts a run
		  -- and immediately re-fires must be debounced by the run it just
		  -- started, or the cooldown would only take effect after the first run
		  -- happens to complete.
		  AND (
		    w.min_cooldown_seconds = 0
		    OR NOT EXISTS (
		      SELECT 1
		      FROM runs recent
		      WHERE recent.watcher_id = w.id
		        AND recent.run_type = 'behavior'
		        AND recent.created_at >
		            now() - make_interval(secs => w.min_cooldown_seconds)
		    )
		  )
		ORDER BY w.id ASC
	`;

  const matches: MatchingBehaviorActivation[] = [];
  for (const row of rows) {
    const triggers = Array.isArray(row.triggers)
      ? (row.triggers as BehaviorEventTrigger[])
      : [];
    // Multi-trigger Behaviors OR activations: any matching event trigger is
    // enough to run once. When several match the same signal, the first in
    // array order supplies execution/output/active_run (UI documents this).
    const [trigger] = matchingBehaviorTriggers(
      triggers.filter(
        (candidate): candidate is BehaviorEventTrigger =>
          candidate.kind === "event",
      ),
      signal,
    );
    if (!trigger) continue;
    matches.push({
      behaviorId: Number(row.id),
      organizationId: String(row.organization_id),
      agentId: String(row.agent_id),
      deviceWorkerId:
        typeof row.device_worker_id === "string" ? row.device_worker_id : null,
      agentKind: typeof row.agent_kind === "string" ? row.agent_kind : null,
      model: typeof row.model === "string" ? row.model : null,
      instructions: typeof row.prompt === "string" ? row.prompt : "",
      trigger,
    });
  }
  return matches;
}

/**
 * Resolve a Chat SDK runtime id to the integer connection id used by Behavior
 * triggers, then perform the normal connector-neutral match. Runtime ids are
 * deliberately stable slugs (for example `slackinst-…`), not database ids.
 */
export async function planBehaviorActivationsForRuntimeConnection(
  args: RuntimeConnectionBehaviorLookup,
  db: DbClient = getDb(),
): Promise<BehaviorActivationPlan> {
  const connections = await db<{ id: number }>`
		SELECT id
		FROM connections
		WHERE organization_id = ${args.connectionOrganizationId}
		  AND slug = ${runtimeConnectionIdToSlug(args.runtimeConnectionId)}
		  AND connector_key = ${args.signal.connector_key}
		  AND deleted_at IS NULL
		LIMIT 1
  `;
  const connectionId = connections[0]?.id;
  if (connectionId == null) return planBehaviorActivations(args.signal, []);
  const signal = { ...args.signal, connection_id: Number(connectionId) };
  const matches = await findMatchingBehaviorActivations(
    args.connectionOrganizationId,
    signal,
    db,
    { crossOrganization: args.crossOrganization },
  );
  return planBehaviorActivations(signal, matches);
}

/**
 * Durably queue a precomputed set of Behavior activations. `db` must be an
 * open transaction when provided; when omitted, each run creation opens its
 * own so the per-Behavior lock and coalesce reads stay replica-safe.
 */
export async function queueBehaviorActivations(args: {
  matches: MatchingBehaviorActivation[];
  signal: ConnectorTriggerSignal;
  db?: DbClient;
}): Promise<BehaviorActivationResult[]> {
  if (args.matches.length === 0) return [];
  const results: BehaviorActivationResult[] = [];
  for (const match of args.matches) {
    const queued = await createBehaviorEventRun(
      {
        organizationId: match.organizationId,
        watcherId: match.behaviorId,
        agentId: match.agentId,
        trigger: match.trigger,
        signal: args.signal,
        deviceWorkerId: match.deviceWorkerId,
        agentKind: match.agentKind,
      },
      args.db,
    );
    results.push({
      ...queued,
      behaviorId: match.behaviorId,
      trigger: match.trigger,
    });
  }

  return results;
}

/** Match a normalized signal and durably queue its Behavior runs. */
export async function activateBehaviorSignal(args: {
  organizationId: string;
  signal: ConnectorTriggerSignal;
  db?: DbClient;
}): Promise<BehaviorActivationResult[]> {
  const sql = args.db ?? getDb();
  const matches = await findMatchingBehaviorActivations(
    args.organizationId,
    args.signal,
    sql,
  );
  return queueBehaviorActivations({
    matches,
    signal: args.signal,
    db: args.db,
  });
}

/**
 * Start newly durable Behavior runs without failing an already-committed
 * connector delivery if the immediate dispatcher itself throws. The periodic
 * automation tick recovers any claim stranded by that failure.
 */
export async function dispatchBehaviorRunsBestEffort(
  results: Array<{ runId: number; status: string }>,
): Promise<void> {
  const runIds = results
    .filter((result) => result.status === "pending")
    .map((result) => result.runId);
  if (runIds.length === 0) return;
  try {
    await dispatchPendingWatcherRuns({ runIds });
  } catch (error) {
    logger.error(
      { error, runIds },
      "Immediate Behavior dispatch threw; automation will recover stranded claims",
    );
  }
}

