23	   * The Behavior's `min_cooldown_seconds`. Carried on the match so a caller can
24	   * skip the cooldown claim entirely for the overwhelming majority of
25	   * Behaviors, which leave it at the 0 default. This is a feature-enabled hint,
26	   * NOT the decision: the window is re-read and consumed authoritatively under
27	   * the per-Behavior lock in `claimBehaviorCooldown`.
28	   */
29	  minCooldownSeconds: number;
30	  trigger: BehaviorEventTrigger;
31	}
32	
33	export interface BehaviorActivationResult extends BehaviorEventRunQueued {
34	  behaviorId: number;
35	  trigger: BehaviorEventTrigger;
36	}
37	
38	export interface BehaviorActivationPlan {
39	  signal: ConnectorTriggerSignal;
40	  replyTargets: MatchingBehaviorActivation[];
41	  backgroundTargets: MatchingBehaviorActivation[];
42	}
43	
44	export interface RuntimeConnectionBehaviorLookup {
45	  connectionOrganizationId: string;
46	  runtimeConnectionId: string;
47	  signal: ConnectorTriggerSignal;
48	  crossOrganization?: boolean;
49	}
50	
51	/**
52	 * Split matching Behaviors once, at the connector-neutral activation seam.
53	 * Reply targets stay with the chat transport so they retain thread history,
54	 * attachments, and live steering; every other target uses the durable run
55	 * queue. Connectors never implement this policy themselves.
56	 */
57	export function planBehaviorActivations(
58	  signal: ConnectorTriggerSignal,
59	  matches: MatchingBehaviorActivation[],
60	): BehaviorActivationPlan {
61	  const replyTargets: MatchingBehaviorActivation[] = [];
62	  const backgroundTargets: MatchingBehaviorActivation[] = [];
63	  for (const match of matches) {
64	    if (
65	      (match.trigger.execution ?? "turn") === "turn" &&
66	      (match.trigger.output ?? "silent") === "reply_to_source"
67	    ) {
68	      replyTargets.push(match);
69	    } else {
70	      backgroundTargets.push(match);
71	    }
72	  }
73	  return { signal, replyTargets, backgroundTargets };
74	}
75	
76	/** Connector-neutral Behavior lookup used by webhooks, pollers, and chat. */
77	export async function findMatchingBehaviorActivations(
78	  organizationId: string,
79	  signal: ConnectorTriggerSignal,
80	  db: DbClient = getDb(),
81	  options?: { crossOrganization?: boolean },
82	): Promise<MatchingBehaviorActivation[]> {
83	  // Coarse GIN needle: kind + connector_key. When the signal carries a
84	  // connection_id, match that connection's triggers OR connector-wide triggers
85	  // (no connection_id on the trigger element). Without the connection arm the
86	  // org-scoped query pulled every Behavior for the connector across all
87	  // connections; the connection arm alone would drop connector-wide drafts.
88	  const baseNeedle = {
89	    kind: "event" as const,
90	    connector_key: signal.connector_key,
91	  };
92	  const organizationFilter = options?.crossOrganization
93	    ? db``
94	    : db`AND w.organization_id = ${organizationId}`;
95	  const connectionId = signal.connection_id;
96	  const triggerFilter =
97	    connectionId != null
98	      ? db`(
99	          w.triggers @> ${db.json([{ ...baseNeedle, connection_id: connectionId }])}::jsonb
100	          OR EXISTS (
101	            SELECT 1
102	            FROM jsonb_array_elements(COALESCE(w.triggers, '[]'::jsonb)) t
103	            WHERE t->>'kind' = 'event'
104	              AND t->>'connector_key' = ${signal.connector_key}
105	              AND t->>'connection_id' IS NULL
106	          )
107	        )`
108	      : db`w.triggers @> ${db.json([baseNeedle])}::jsonb`;
109	  const rows = await db`
110			SELECT w.id, w.organization_id, w.agent_id, w.device_worker_id::text AS device_worker_id,
111			       w.agent_kind, w.triggers, w.execution_config->>'model' AS model,
112			       w.min_cooldown_seconds, v.prompt
113			FROM watchers w
114			JOIN watcher_versions v ON v.id = w.current_version_id
115			WHERE w.status = 'active'
116			  AND w.agent_id IS NOT NULL
117			  AND ${triggerFilter}
118			  ${organizationFilter}
119			ORDER BY w.id ASC
120		`;
121	
122	  const matches: MatchingBehaviorActivation[] = [];
123	  for (const row of rows) {
124	    const triggers = Array.isArray(row.triggers)
125	      ? (row.triggers as BehaviorEventTrigger[])
126	      : [];
127	    // Multi-trigger Behaviors OR activations: any matching event trigger is
128	    // enough to run once. When several match the same signal, the first in
129	    // array order supplies execution/output/active_run (UI documents this).
130	    const [trigger] = matchingBehaviorTriggers(
131	      triggers.filter(
132	        (candidate): candidate is BehaviorEventTrigger =>
133	          candidate.kind === "event",
134	      ),
135	      signal,
136	    );
137	    if (!trigger) continue;
