139	      behaviorId: Number(row.id),
140	      organizationId: String(row.organization_id),
141	      agentId: String(row.agent_id),
142	      deviceWorkerId:
143	        typeof row.device_worker_id === "string" ? row.device_worker_id : null,
144	      agentKind: typeof row.agent_kind === "string" ? row.agent_kind : null,
145	      model: typeof row.model === "string" ? row.model : null,
146	      instructions: typeof row.prompt === "string" ? row.prompt : "",
