// Boot a throwaway embedded Postgres (with pgvector) for the integration suite.
// Prints the DATABASE_URL, then stays alive until SIGTERM.
import { existsSync, mkdtempSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import http from "node:http";

const serverSrc = process.argv[2];
const { embeddedPgOptions, hydrateEmbeddedPgSymlinks } = await import(
  join(serverSrc, "src/embedded-runtime.ts")
);
const { default: EmbeddedPostgres } = await import("embedded-postgres");
const { injectPgvector, resolveEmbeddedNativeDir } = await import(
  "@lobu/pgvector-embedded"
);

const nativeDir = resolveEmbeddedNativeDir();
hydrateEmbeddedPgSymlinks(nativeDir);
injectPgvector(nativeDir);

const port = await new Promise((resolve, reject) => {
  const srv = http.createServer();
  srv.listen(0, "127.0.0.1", () => {
    const { port } = srv.address();
    srv.close(() => resolve(port));
  });
  srv.on("error", reject);
});

const dataDir = mkdtempSync(join(tmpdir(), "lobu-test-pg-"));
const pg = new EmbeddedPostgres(embeddedPgOptions(dataDir, port));
if (!existsSync(join(dataDir, "PG_VERSION"))) await pg.initialise();
await pg.start();
await pg.createDatabase("lobu_test");

const url = `REDACTED`;
console.log(`READY ${url}`);

const shutdown = async () => {
  try {
    await pg.stop();
  } catch {}
  process.exit(0);
};
process.on("SIGTERM", shutdown);
process.on("SIGINT", shutdown);
setInterval(() => {}, 1 << 30);

