70	function behaviorEventTriggerKey(trigger: BehaviorEventTrigger): string {
71	  return stableJson({
72	    kind: 'event',
73	    connector_key: trigger.connector_key,
74	    connection_id: trigger.connection_id ?? null,
75	    event_types: [...trigger.event_types].sort(),
76	    match: trigger.match ?? null,
77	    execution: trigger.execution ?? 'turn',
