84	const WATCHER_EXECUTION_UNIQUE_INDEX = 'idx_runs_executing_per_behavior';
85	
86	/**
87	 * Claim one pending Behavior run while holding the durable per-Behavior row
88	 * lock. Both the server dispatcher and device poller use this transition so
89	 * replicas cannot promote different queued runs from the same Behavior at the
90	 * same time.
91	 */
92	export async function claimPendingWatcherRun(
93	  tx: DbClient,
94	  params: {
95	    runId: number;
96	    watcherId: number;
97	    claimedBy: string;
98	    status: 'claimed' | 'running';
99	  }
100	): Promise<boolean> {
101	  const watcher = await tx`
102	    SELECT id
103	    FROM watchers
104	    WHERE id = ${params.watcherId}
105	    FOR UPDATE SKIP LOCKED
106	  `;
107	  if (watcher.length === 0) return false;
108	
109	  try {
110	    const claimed = await tx.savepoint(
111	      async (sp) => sp`
112	        UPDATE runs r
113	        SET status = ${params.status},
114	            claimed_at = current_timestamp,
115	            last_heartbeat_at = CASE
116	              WHEN ${params.status}::text = 'running' THEN current_timestamp
117	              ELSE r.last_heartbeat_at
118	            END,
119	            claimed_by = ${params.claimedBy}
120	        WHERE r.id = ${params.runId}
121	          AND r.watcher_id = ${params.watcherId}
122	          AND r.run_type = 'behavior'
123	          AND r.status = 'pending'
124	          AND NOT EXISTS (
125	            SELECT 1
126	            FROM runs active
127	            WHERE active.watcher_id = r.watcher_id
128	              AND active.run_type = 'behavior'
129	              AND active.status IN ('claimed', 'running')
130	          )
131	        RETURNING r.id
132	      `
133	    );
134	    return claimed.length > 0;
135	  } catch (error) {
136	    // During a rolling deployment an older replica may still claim without
137	    // taking the watcher row lock. The unique index remains authoritative;
138	    // contain that expected contention inside the savepoint and skip the run.
139	    if (isUniqueViolation(error, WATCHER_EXECUTION_UNIQUE_INDEX)) return false;
140	    throw error;
141	  }
142	}
