1	import type { DbClient } from "../db/client";
2	import { getDb } from "../db/client";
3	import logger from "../utils/logger";
4	
5	/**
6	 * `watchers.min_cooldown_seconds` debounce for event-triggered Behaviors.
7	 *
8	 * A Behavior activates on an event through two substrates: background targets
9	 * become durable `behavior` runs via `createBehaviorEventRun`, and
10	 * `reply_to_source` targets are handed to the chat transport and never write a
11	 * run row at all. A predicate over `runs` would therefore be a silent no-op on
12	 * exactly one half of the feature, so both paths claim the same cursor
13	 * (`watchers.last_event_activation_at`) through this module.
14	 *
15	 * The claim must be serialized, or two concurrent deliveries both read "no
16	 * recent activation" and both fire. It reuses the advisory lock
17	 * `createBehaviorEventRun` already takes per Behavior rather than introducing
18	 * a second one: the lock is transaction-scoped, so the read and the cursor
19	 * write cannot interleave with another replica's.
20	 */
21	const BEHAVIOR_ACTIVATION_LOCK_NAMESPACE = "behavior_event_run";
22	
23	/**
24	 * Serialize activation decisions for one Behavior. Transaction-scoped: the
25	 * lock is released when `tx` commits or rolls back.
26	 */
27	export async function lockBehaviorForActivation(
28	  tx: DbClient,
29	  watcherId: number,
30	): Promise<void> {
31	  await tx`
32	    SELECT pg_advisory_xact_lock(
33	      hashtext(${BEHAVIOR_ACTIVATION_LOCK_NAMESPACE}),
34	      ${watcherId}
35	    )
36	  `;
37	}
38	
39	/**
40	 * Consume this Behavior's cooldown window, returning whether the activation
41	 * may proceed. Callers MUST already hold `lockBehaviorForActivation` on the
42	 * same transaction — the read and the write below are only atomic together.
43	 *
44	 * A Behavior with `min_cooldown_seconds = 0` (the NOT NULL default, and the
45	 * overwhelming majority) is always allowed and never writes the cursor, so the
46	 * common path costs one indexed read and no row contention.
47	 *
48	 * Returns false for a Behavior that no longer exists: a deleted Behavior has
49	 * nothing to activate.
50	 */
51	export async function claimBehaviorCooldown(
52	  tx: DbClient,
53	  watcherId: number,
54	): Promise<boolean> {
55	  const rows = await tx`
56	    SELECT
57	      min_cooldown_seconds,
58	      last_event_activation_at IS NOT NULL
59	        AND last_event_activation_at >
60	            clock_timestamp() - make_interval(secs => min_cooldown_seconds)
61	        AS within_cooldown
62	    FROM watchers
63	    WHERE id = ${watcherId}
64	    LIMIT 1
65	  `;
66	  const row = rows[0];
67	  if (!row) {
68	    logger.warn(
69	      { watcherId },
70	      "[cooldown] Behavior row missing while claiming an activation — suppressing",
71	    );
72	    return false;
73	  }
74	  const cooldownSeconds = Number(row.min_cooldown_seconds ?? 0);
75	  if (!(cooldownSeconds > 0)) return true;
76	  if (row.within_cooldown === true) {
77	    logger.info(
78	      { watcherId, cooldownSeconds },
79	      "[cooldown] Suppressing Behavior activation inside its min_cooldown_seconds window",
80	    );
81	    return false;
82	  }
83	  await tx`
84	    UPDATE watchers
85	    SET last_event_activation_at = clock_timestamp()
86	    WHERE id = ${watcherId}
87	  `;
88	  return true;
89	}
90	
91	/**
92	 * Claim the cooldown for a caller that has no ambient transaction — the chat
93	 * reply path, which does not create a run row. Opens its own short transaction
94	 * so the lock scope stays tight.
95	 *
96	 * The window is consumed at the moment of the claim, not when the turn is
97	 * delivered: a caller that throws after claiming burns one window. That is the
98	 * right trade for a debounce (at worst one event is dropped) and the opposite
99	 * choice — claiming after delivery — would let a concurrent burst through.
100	 * Database failures propagate so the inbound delivery can retry; they must
101	 * never be reported as an ordinary cooldown suppression.
102	 */
103	export async function claimBehaviorCooldownStandalone(
104	  watcherId: number,
105	  db?: DbClient,
106	): Promise<boolean> {
107	  const sql = db ?? getDb();
108	  try {
109	    return await sql.begin(async (tx: DbClient) => {
110	      await lockBehaviorForActivation(tx, watcherId);
111	      return await claimBehaviorCooldown(tx, watcherId);
112	    });
113	  } catch (error) {
114	    logger.error(
115	      { error, watcherId },
116	      "[cooldown] Could not claim a Behavior cooldown window — retrying the activation",
117	    );
118	    throw error;
119	  }
120	}

