/**
 * E2E driver against a booted worktree gateway.
 *
 * Usage: bun e2e.mjs <repoRoot> <baseUrl> <databaseUrl> <case>
 *   case=intent    #2340 — the real dispatcher must still get a session, and a
 *                  forged intent from an ordinary token must be refused.
 *   case=cooldown  #2341 — a cooldown Behavior fires once across two event
 *                  deliveries; a cooldown=0 Behavior is unaffected.
 */
import { createHash, randomBytes } from "node:crypto";
import { join } from "node:path";

const [repo, baseUrl, databaseUrl, testCase] = process.argv.slice(2);
const postgres = (await import(join(repo, "node_modules/postgres/src/index.js")))
  .default;
const sql = postgres(databaseUrl, { onnotice: () => {} });

const log = (...a) => console.log(...a);
let failures = 0;
function check(name, ok, detail = "") {
  log(`${ok ? "PASS" : "FAIL"}  ${name}${detail ? ` — ${detail}` : ""}`);
  if (!ok) failures++;
}

// ---------------------------------------------------------------- PAT + MCP
async function mintPat(orgId, userId) {
  const token = `owl_pat_${randomBytes(24).toString("base64url")}`;
  await sql`
    INSERT INTO personal_access_tokens (
      id, user_id, organization_id, name, token_hash, token_prefix, scopes
    ) VALUES (
      ${randomBytes(16).toString("hex")}, ${userId}, ${orgId}, 'e2e',
      ${createHash("sha256").update(token).digest("hex")},
      ${token.slice(0, 12)}, ${"mcp:read mcp:write mcp:admin"}
    )
  `;
  return token;
}

async function mcp(orgSlug, pat, agentId) {
  const url = `${baseUrl}/mcp/${orgSlug}`;
  const headers = {
    Authorization: `Bearer ${pat}`,
    "Content-Type": "application/json",
    Accept: "application/json, text/event-stream",
    "x-lobu-agent-id": agentId,
  };
  const init = await fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify({
      jsonrpc: "2.0",
      id: 1,
      method: "initialize",
      params: {
        protocolVersion: "2024-11-05",
        capabilities: {},
        clientInfo: { name: "e2e", version: "1" },
      },
    }),
  });
  const sessionId = init.headers.get("mcp-session-id");
  if (!sessionId) throw new Error(`no mcp-session-id (${init.status})`);
  const withSession = { ...headers, "mcp-session-id": sessionId };
  await fetch(url, {
    method: "POST",
    headers: withSession,
    body: JSON.stringify({ jsonrpc: "2.0", method: "notifications/initialized" }),
  });
  let id = 10;
  return async function call(name, args) {
    const res = await fetch(url, {
      method: "POST",
      headers: withSession,
      body: JSON.stringify({
        jsonrpc: "2.0",
        id: id++,
        method: "tools/call",
        params: { name, arguments: args },
      }),
    });
    const text = await res.text();
    const line = text.split("\n").find((l) => l.startsWith("data: "));
    const payload = JSON.parse(line ? line.slice(6) : text);
    const content = payload.result?.content?.[0]?.text;
    return {
      raw: payload,
      isError: payload.result?.isError === true || payload.error != null,
      text: content ?? JSON.stringify(payload.error ?? payload.result ?? {}),
    };
  };
}

// ------------------------------------------------------------------ fixture
async function workspace() {
  const [org] = await sql`SELECT id, slug FROM organization ORDER BY id LIMIT 1`;
  const [user] = await sql`SELECT id FROM "user" ORDER BY id LIMIT 1`;
  const [agent] = await sql`
    SELECT id FROM agents WHERE organization_id = ${org.id} ORDER BY id LIMIT 1
  `;
  return { org, user, agent };
}

// ---------------------------------------------------------------- #2340
async function intentCase() {
  const { org, user, agent } = await workspace();
  log(`org=${org.slug} agent=${agent.id}`);
  const pat = await mintPat(org.id, user.id);
  const call = await mcp(org.slug, pat, agent.id);

  const created = await call("manage_behaviors", {
    action: "create",
    slug: `e2e-intent-${Date.now()}`,
    name: "E2E intent",
    prompt: "Say hello.",
    agent_id: agent.id,
    execution_config: { permission_mode: "bypassPermissions" },
  });
  const behaviorId = JSON.parse(created.text).behavior_id;
  check("Behavior created with permission_mode", !created.isError, created.text.slice(0, 200));
  if (created.isError) return;

  // THE test: the real dispatcher must still obtain a session. `trigger`
  // dispatches synchronously and rethrows the run's error_message.
  const fired = await call("manage_behaviors", { action: "trigger", behavior_id: String(behaviorId) });
  const brokeDispatch = /Failed to create or resume Lobu agent session/i.test(fired.text);
  check(
    "real dispatcher is NOT rejected by intent verification",
    !brokeDispatch,
    brokeDispatch ? fired.text.slice(0, 300) : `dispatch outcome: ${fired.text.slice(0, 160)}`,
  );

  // A forged intent naming that same in-flight run, from an ordinary token.
  const [run] = await sql`
    SELECT id FROM runs WHERE watcher_id = ${behaviorId} AND run_type = 'behavior'
    ORDER BY id DESC LIMIT 1
  `;
  if (run) {
    const forged = await fetch(`${baseUrl}/api/v1/agents`, {
      method: "POST",
      headers: { Authorization: `Bearer ${pat}`, "Content-Type": "application/json" },
      body: JSON.stringify({
        agentId: agent.id,
        forceNew: true,
        intent: { kind: "behavior_run", runId: Number(run.id), behaviorId: Number(behaviorId) },
      }),
    });
    check("forged intent from an ordinary token is refused", forged.status === 403,
      `HTTP ${forged.status}: ${(await forged.text()).slice(0, 160)}`);
  } else {
    check("a run row exists to forge against", false);
  }

  // A crafted suffix with no intent at all must never produce the correlation.
  const crafted = await fetch(`${baseUrl}/api/v1/agents`, {
    method: "POST",
    headers: { Authorization: `Bearer ${pat}`, "Content-Type": "application/json" },
    body: JSON.stringify({
      agentId: agent.id, userId: "caller", thread: "topic_watcher_5_run_1", forceNew: true,
    }),
  });
  const craftedBody = await crafted.text();
  const leaked = crafted.status === 201 && /_watcher_\d+_run_\d+"/.test(craftedBody);
  check("crafted conversation suffix never reaches a session", !leaked,
    `HTTP ${crafted.status}: ${craftedBody.slice(0, 160)}`);
}

// ---------------------------------------------------------------- #2341
async function cooldownCase() {
  const { org, user, agent } = await workspace();
  log(`org=${org.slug} agent=${agent.id}`);
  const pat = await mintPat(org.id, user.id);
  const call = await mcp(org.slug, pat, agent.id);

  const [conn] = await sql`
    INSERT INTO connections (organization_id, connector_key, slug, name, created_by, status)
    VALUES (${org.id}, 'github', ${`e2e-gh-${Date.now()}`}, 'E2E GitHub', ${user.id}, 'active')
    RETURNING id
  `;

  async function makeBehavior(cooldown) {
    const res = await call("manage_behaviors", {
      action: "create",
      slug: `e2e-cd-${cooldown}-${Date.now()}`,
      name: `E2E cooldown ${cooldown}`,
      prompt: "Summarize.",
      agent_id: agent.id,
      min_cooldown_seconds: cooldown,
      triggers: [{
        kind: "event", connector_key: "github", connection_id: Number(conn.id),
        event_types: ["pull_request.updated"], execution: "window",
        active_run: "queue", output: "silent",
      }],
    });
    if (res.isError) throw new Error(`create failed: ${res.text.slice(0, 300)}`);
    return Number(JSON.parse(res.text).behavior_id);
  }

  const cooling = await makeBehavior(1800);
  const normal = await makeBehavior(0);
  check("Behaviors created (cooldown 1800 and 0)", true, `${cooling}, ${normal}`);

  // Two real deliveries through the ingest surface the connectors use.
  const { activateBehaviorSignal, dispatchBehaviorRunsBestEffort } = await import(
    join(repo, "packages/server/src/behaviors/activation.ts")
  );
  process.env.DATABASE_URL = databaseUrl;
  for (const n of [1, 2]) {
    const results = await activateBehaviorSignal({
      organizationId: org.id,
      signal: {
        connector_key: "github", connection_id: Number(conn.id),
